window.songs=[{"order":1,"id":"01-mais-il-l-aimait","title":"Mais il l'aimait","titleZh":"可他始终爱着她","lines":[{"id":"cyrano-de-bergerac-01-001","lineIndex":1,"speaker":"","original":"Dans l'ombre du jour qui s'en va","ipa":"/dɑ̃ lɔ̃bʁ dy ʒuʁ ki sɑ̃ va/","zh":"在逐渐消逝的白昼阴影中","en":"In the shadow of the fading day","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-01-002","lineIndex":2,"speaker":"","original":"Il marche vacillant tombant à chaque pas","ipa":"/il maʁʃ vasijɑ̃ tɔ̃bɑ̃ a ʃak pa/","zh":"他踉跄行走 步步跌跤","en":"He walks wavering, falling with every step","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-01-003","lineIndex":3,"speaker":"","original":"Il livre son dernier combat","ipa":"/il livʁ sɔ̃ dɛʁnje kɔ̃ba/","zh":"他进行着最后的战斗","en":"He fights his last battle","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-01-004","lineIndex":4,"speaker":"","original":"Contre la lâcheté, le mensonge il se bat","ipa":"/kɔ̃tʁ la laʃte lə mɑ̃sɔ̃ʒ il sə ba/","zh":"他抗击着懦弱与谎言","en":"Against cowardice, lies he fights","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-01-005","lineIndex":5,"speaker":"","original":"C'est sans espoir, mais il se bat","ipa":"/sɛ sɑ̃z ɛspwaʁ mɛz il sə ba/","zh":"没有希望，但他仍在战斗","en":"It's hopeless, but he fights","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-01-006","lineIndex":6,"speaker":"","original":"Il est trop tard mais il se bat","ipa":"/il ɛ tʁo taʁ mɛz il sə ba/","zh":"为时已晚，但他仍在战斗","en":"It's too late but he fights","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-01-007","lineIndex":7,"speaker":"","original":"Il fixe la mort qui l'attend","ipa":"/il fiks la mɔʁ ki latɑ̃/","zh":"他凝视着等待他的死亡","en":"He stares at the death that awaits him","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-01-008","lineIndex":8,"speaker":"","original":"Dans son regard voilé du rouge de son sang","ipa":"/dɑ̃ sɔ̃ ʁəɡaʁ vwale dy ʁuʒ də sɔ̃ sɑ̃/","zh":"他的目光蒙上了自己鲜血的殷红","en":"In his eyes veiled with the red of his blood","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-01-009","lineIndex":9,"speaker":"","original":"Il devine celle qu'il aimait tant","ipa":"/il dəvin sɛl kil ɛmɛ tɑ̃/","zh":"他辨认出他曾深爱的那张脸庞","en":"He guesses the one he loved so much","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-01-010","lineIndex":10,"speaker":"","original":"Pour la première fois le regarder vraiment","ipa":"/puʁ la pʁəmjɛʁ fwa lə ʁəɡaʁde vʁɛmɑ̃/","zh":"她第一次真正地注视着他","en":"For the first time really looking at him","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-01-011","lineIndex":11,"speaker":"","original":"Mais il l'aimait","ipa":"/mɛz il lɛmɛ/","zh":"但他早已","en":"But he loved her","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-01-012","lineIndex":12,"speaker":"","original":"Depuis longtemps","ipa":"/dəpɥi lɔ̃tɑ̃/","zh":"长久地爱着她","en":"For a long time","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-01-013","lineIndex":13,"speaker":"","original":"Comme il l'aimait","ipa":"/kɔm il lɛmɛ/","zh":"正如他长久地爱着她","en":"As he loved her","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-01-014","lineIndex":14,"speaker":"","original":"Et maintenant","ipa":"/e mɛ̃tnɑ̃/","zh":"而现在","en":"And now","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-01-015","lineIndex":15,"speaker":"","original":"Elle sait pour la première fois","ipa":"/ɛl sɛ puʁ la pʁəmjɛʁ fwa/","zh":"她第一次知道","en":"She knows for the first time","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-01-016","lineIndex":16,"speaker":"","original":"Que c'est lui qu'elle aimait, lui qu'elle ne voyait pas","ipa":"/kə sɛ lɥi kɛl ɛmɛ lɥi kɛl nə vwajɛ pa/","zh":"她爱的是他 是她从未看清过的他","en":"That it was him she loved, him whom she did not see","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-01-017","lineIndex":17,"speaker":"","original":"Ce roc inamovible qui était toujours là","ipa":"/sə ʁɔk inamovibl ki etɛ tuʒuʁ la/","zh":"那块始终在那里的 不可撼动的磐石","en":"This immovable rock which was always there","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-01-018","lineIndex":18,"speaker":"","original":"Tout cet amour c'était sa voix","ipa":"/tu sɛt amuʁ setɛ sa vwa/","zh":"所有的爱曾是他的声音","en":"All this love was his voice","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-01-019","lineIndex":19,"speaker":"","original":"Ses mots dans l'ombre d'une autre voix","ipa":"/se mo dɑ̃ lɔ̃bʁ dyn otʁ vwa/","zh":"是藏于另一个声音阴影中的他的话语","en":"His words in the shadow of another voice","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-01-020","lineIndex":20,"speaker":"","original":"Et il l'aimait...","ipa":"/e il lɛmɛ/","zh":"而他爱着她…","en":"And he loved her...","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-01-022","lineIndex":21,"speaker":"","original":"Et quand il rentrera chez Dieu","ipa":"/e kɑ̃t il ʁɑ̃tʁəʁa ʃe djø/","zh":"当他回到上帝那里","en":"And when he goes home to God","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-01-023","lineIndex":22,"speaker":"","original":"Son salut balaiera largement le seuil bleu","ipa":"/sɔ̃ saly balɛʁa laʁʒəmɑ̃ lə sœj blø/","zh":"他的问候将拂过宽阔的蓝色门槛","en":"His greeting will sweep wide across the blue threshold","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-01-024","lineIndex":23,"speaker":"","original":"Il garde son panache même s'il ferme les yeux","ipa":"/il ɡaʁd sɔ̃ panaʃ mɛm sil fɛʁm lez jø/","zh":"即使闭上眼睛，他依然保持着他的风采","en":"He keeps his panache even if he closes his eyes","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-01-025","lineIndex":24,"speaker":"","original":"C'était sa vie c'est son combat","ipa":"/setɛ sa vi sɛ sɔ̃ kɔ̃ba/","zh":"那是他的生命，这是他的战斗","en":"It was his life, it's his fight","note":"","sourceLineIndex":25},{"id":"cyrano-de-bergerac-01-026","lineIndex":25,"speaker":"","original":"L'amour le tue mais il vivra","ipa":"/lamuʁ lə ty mɛz il vivʁa/","zh":"爱杀死了他，但他将活下去","en":"Love kills him but he will live","note":"","sourceLineIndex":26},{"id":"cyrano-de-bergerac-01-027","lineIndex":26,"speaker":"","original":"Comme il l'aimait … elle l'aimera … elle l'aimera","ipa":"/kɔm il lɛmɛ ɛl lɛmʁa ɛl lɛmʁa/","zh":"正如他爱她...她也将爱他...永世牵挂","en":"As he loved her... she will love him... she will love him","note":"","sourceLineIndex":27}],"sourceOrder":1,"displayOrder":1},{"order":2,"id":"02-marchand-de-rimes","title":"Marchand de rimes","titleZh":"诗韵商人","lines":[{"id":"cyrano-de-bergerac-02-001","lineIndex":1,"speaker":"","original":"Assis devant ma feuille blanche","ipa":"/asi dəvɑ̃ ma fœj blɑ̃ʃ/","zh":"独对白纸","en":"Sitting in front of my blank sheet","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-02-002","lineIndex":2,"speaker":"","original":"Miroir de l'âme","ipa":"/miʁwaʁ də lam/","zh":"灵魂之镜","en":"Mirror of the soul","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-02-003","lineIndex":3,"speaker":"","original":"Des idées noires en avalanche, pourtant","ipa":"/dez ide nwaʁz ɑ̃n avalɑ̃ʃ puʁtɑ̃/","zh":"黑暗的思绪如雪崩般涌来 可是啊","en":"Dark thoughts in avalanche, however","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-02-004","lineIndex":4,"speaker":"","original":"La nuit est si calme","ipa":"/la nɥi ɛ si kalm/","zh":"夜色如此宁静","en":"The night is so calm","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-02-005","lineIndex":5,"speaker":"","original":"Assis devant ma feuille blanche","ipa":"/asi dəvɑ̃ ma fœj blɑ̃ʃ/","zh":"坐在我的白纸前","en":"Sitting in front of my blank sheet","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-02-006","lineIndex":6,"speaker":"","original":"Je pense à elle","ipa":"/ʒə pɑ̃s a ɛl/","zh":"心中念她","en":"I think of her","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-02-007","lineIndex":7,"speaker":"","original":"Et chaque nuit mon âme flanche, mon Dieu","ipa":"/e ʃak nɥi mɔ̃n am flɑ̃ʃ mɔ̃ djø/","zh":"而每个夜晚我的灵魂都在沦陷 上帝啊","en":"And every night my soul fails, my God","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-02-008","lineIndex":8,"speaker":"","original":"Elle est si belle...","ipa":"/ɛl ɛ si bɛl/","zh":"她是如此美丽...","en":"She is so beautiful...","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-02-009","lineIndex":9,"speaker":"","original":"Je n'ose pas","ipa":"/ʒə nɔz pa/","zh":"我不敢","en":"I don't dare","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-02-010","lineIndex":10,"speaker":"","original":"Lui dire tout bas","ipa":"/lɥi diʁ tu ba/","zh":"低声对她说","en":"Tell her quietly","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-02-011","lineIndex":11,"speaker":"","original":"Je n'ose pas","ipa":"/ʒə nɔz pa/","zh":"我不敢","en":"I don't dare","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-02-012","lineIndex":12,"speaker":"","original":"Lui dire tout ça","ipa":"/lɥi diʁ tu sa/","zh":"对她说出这一切","en":"Tell her all that","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-02-013","lineIndex":13,"speaker":"","original":"Je n'suis qu'un auteur de chanson","ipa":"/ʒə nsɥi kœ̃n otœʁ də ʃɑ̃sɔ̃/","zh":"我不过是个写歌的人","en":"I'm just an author of songs","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-02-014","lineIndex":14,"speaker":"","original":"Un marchand de lignes","ipa":"/œ̃ maʁʃɑ̃ də linj/","zh":"一个贩卖词句的商贩","en":"A merchant of lines","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-02-015","lineIndex":15,"speaker":"","original":"Qui vend au poids ses émotions","ipa":"/ki vɑ̃t o pwa sez emosjɔ̃/","zh":"按重量兜售自己的情感","en":"Who sells his emotions by weight","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-02-016","lineIndex":16,"speaker":"","original":"Maquillées de rimes","ipa":"/makije də ʁim/","zh":"用韵脚乔装打扮","en":"Made up of rhymes","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-02-017","lineIndex":17,"speaker":"","original":"Je n'ose pas","ipa":"/ʒə nɔz pa/","zh":"我不敢","en":"I don't dare","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-02-018","lineIndex":18,"speaker":"","original":"Lui dire tout bas","ipa":"/lɥi diʁ tu ba/","zh":"低声对她说","en":"Tell her quietly","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-02-019","lineIndex":19,"speaker":"","original":"Non, je n'ose pas","ipa":"/nɔ̃ ʒə nɔz pa/","zh":"不 我不敢","en":"No, I don't dare","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-02-020","lineIndex":20,"speaker":"","original":"Lui dire tout ça","ipa":"/lɥi diʁ tu sa/","zh":"对她说出这一切","en":"Tell her all that","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-02-021","lineIndex":21,"speaker":"","original":"J'écris de mon mieux","ipa":"/ʒekʁi də mɔ̃ mjø/","zh":"我竭尽全力","en":"I write as best I can","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-02-022","lineIndex":22,"speaker":"","original":"Des chansons que les autres chantent","ipa":"/de ʃɑ̃sɔ̃ kə lez otʁ ʃɑ̃t/","zh":"写出那些由别人唱的歌","en":"Songs that others sing","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-02-023","lineIndex":23,"speaker":"","original":"En fermant les yeux","ipa":"/ɑ̃ fɛʁmɑ̃ lez jø/","zh":"当他们闭上眼睛","en":"Closing my eyes","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-02-024","lineIndex":24,"speaker":"","original":"Ils disent pour moi","ipa":"/il diz puʁ mwa/","zh":"他们替我说出","en":"They say for me","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-02-025","lineIndex":25,"speaker":"","original":"Ces « je t'aime » que je n'ose pas Roxane…","ipa":"/se ʒə tɛm kə ʒə nɔz pa ʁoksan/","zh":"那些我不敢说出口的“我爱你” 罗克珊…","en":"These “I love you” that I don’t dare Roxane…","note":"","sourceLineIndex":25},{"id":"cyrano-de-bergerac-02-026","lineIndex":26,"speaker":"","original":"C'est pour toi","ipa":"/sɛ puʁ twa/","zh":"这是给你的","en":"It’s for you","note":"","sourceLineIndex":26}],"sourceOrder":2,"displayOrder":2},{"order":3,"id":"03-danseuse-etoile","title":"Danseuse étoile","titleZh":"星辰舞者","lines":[{"id":"cyrano-de-bergerac-03-001","lineIndex":1,"speaker":"","original":"Toute ma vie je danserai","ipa":"/tut ma vi ʒə dɑ̃sʁe/","zh":"我愿一生起舞","en":"All my life I will dance","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-03-002","lineIndex":2,"speaker":"","original":"J'ai tant de pas à inventer","ipa":"/ʒe tɑ̃ də pa a ɛ̃vɑ̃te/","zh":"有太多舞步待我创造","en":"I have so many steps to invent","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-03-003","lineIndex":3,"speaker":"","original":"Tant de courbes pour dessiner","ipa":"/tɑ̃ də kuʁb puʁ dɛsine/","zh":"有太多曲线勾勒美好","en":"So many curves to draw","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-03-004","lineIndex":4,"speaker":"","original":"Mon bonheur","ipa":"/mɔ̃ bɔnœʁ/","zh":"我的幸福","en":"My happiness","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-03-005","lineIndex":5,"speaker":"","original":"J'attendrai les yeux fermés","ipa":"/ʒatɑ̃dʁe lez jø fɛʁme/","zh":"我将闭目静候","en":"I will wait with my eyes closed","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-03-006","lineIndex":6,"speaker":"","original":"Que le rideau soit levé","ipa":"/kə lə ʁido swa ləve/","zh":"待帷幕升起时","en":"For the curtain to be raised","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-03-007","lineIndex":7,"speaker":"","original":"Rentrer sous la lumière des projecteurs","ipa":"/ʁɑ̃tʁe su la lymjɛʁ de pʁoʒɛktœʁ/","zh":"重回那聚光灯的照耀","en":"Return under the light of the Spotlights","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-03-009","lineIndex":8,"speaker":"","original":"J'ai tellement rêvé","ipa":"/ʒe tɛlmɑ̃ ʁɛve/","zh":"我曾如此梦想","en":"I dreamed so much","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-03-010","lineIndex":9,"speaker":"","original":"De m'envoler","ipa":"/də mɑ̃vole/","zh":"振翅飞翔","en":"Of flying away","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-03-011","lineIndex":10,"speaker":"","original":"Danseuse étoile","ipa":"/dɑ̃søz etwal/","zh":"芭蕾舞星","en":"Principal dancer","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-03-012","lineIndex":11,"speaker":"","original":"J'écrirai ma vie en dansant","ipa":"/ʒekʁiʁe ma vi ɑ̃ dɑ̃sɑ̃/","zh":"我以舞步书写生命","en":"I will write my life while dancing","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-03-013","lineIndex":12,"speaker":"","original":"J'en rêve depuis si longtemps","ipa":"/ʒɑ̃ ʁɛv dəpɥi si lɔ̃tɑ̃/","zh":"这梦萦绕多年光阴","en":"I've been dreaming of it for so long","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-03-014","lineIndex":13,"speaker":"","original":"Je danserai, au firmament","ipa":"/ʒə dɑ̃sʁe o fiʁmamɑ̃/","zh":"我将在苍穹起舞","en":"I will dance, in the firmament","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-03-015","lineIndex":14,"speaker":"","original":"Danseuse étoile","ipa":"/dɑ̃søz etwal/","zh":"首席女舞者","en":"Principal dancer","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-03-016","lineIndex":15,"speaker":"","original":"Les salles seront des cathédrales","ipa":"/le sal səʁɔ̃ de katedʁal/","zh":"剧场化作神圣教堂","en":"The halls will be cathedrals","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-03-017","lineIndex":16,"speaker":"","original":"Seule dans la lumière pâle","ipa":"/sœl dɑ̃ la lymjɛʁ pal/","zh":"独舞于苍白光芒","en":"Alone in the pale light","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-03-018","lineIndex":17,"speaker":"","original":"Je danserai","ipa":"/ʒə dɑ̃sʁe/","zh":"我将起舞","en":"I will dance","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-03-019","lineIndex":18,"speaker":"","original":"Sur les étoiles, sur les étoiles…","ipa":"/syʁ lez etwal syʁ lez etwal/","zh":"于星辰之上，于星辰之上…","en":"On the stars, on the stars...","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-03-020","lineIndex":19,"speaker":"","original":"Toute ma vie je danserai","ipa":"/tut ma vi ʒə dɑ̃sʁe/","zh":"我愿一生起舞","en":"All my life I will dance","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-03-021","lineIndex":20,"speaker":"","original":"Des symphonies inachevées","ipa":"/de sɛ̃foniz inaʃve/","zh":"演绎未竟的交响","en":"Unfinished symphonies","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-03-022","lineIndex":21,"speaker":"","original":"Les violons pour aveugler","ipa":"/le vjolɔ̃ puʁ avøɡle/","zh":"让琴声淹没","en":"Violins to blind","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-03-023","lineIndex":22,"speaker":"","original":"La douleur","ipa":"/la dulœʁ/","zh":"所有伤痛","en":"Pain","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-03-024","lineIndex":23,"speaker":"","original":"J'ai tant de rêves à danser","ipa":"/ʒe tɑ̃ də ʁɛvz a dɑ̃se/","zh":"有太多梦境待我舞动","en":"I have so many dreams to dance","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-03-025","lineIndex":24,"speaker":"","original":"Tant de valses pour effacer","ipa":"/tɑ̃ də vals puʁ efase/","zh":"太多圆舞曲将抹去","en":"So many waltzes to erase","note":"","sourceLineIndex":25},{"id":"cyrano-de-bergerac-03-026","lineIndex":25,"speaker":"","original":"Les contretemps et tous les contre cœurs","ipa":"/le kɔ̃tʁətɑ̃ e tu le kɔ̃tʁ kœʁ/","zh":"不合节拍与所有违心","en":"The setbacks and all reluctantly","note":"","sourceLineIndex":26},{"id":"cyrano-de-bergerac-03-027","lineIndex":26,"speaker":"","original":"J'ai tellement rêvé","ipa":"/ʒe tɛlmɑ̃ ʁɛve/","zh":"我曾如此梦想","en":"I dreamed so much","note":"","sourceLineIndex":27},{"id":"cyrano-de-bergerac-03-028","lineIndex":27,"speaker":"","original":"De m'envoler","ipa":"/də mɑ̃vole/","zh":"振翅飞翔","en":"Of flying away","note":"","sourceLineIndex":28},{"id":"cyrano-de-bergerac-03-029","lineIndex":28,"speaker":"","original":"Danseuse étoile","ipa":"/dɑ̃søz etwal/","zh":"芭蕾舞星","en":"Principal dancer","note":"","sourceLineIndex":29},{"id":"cyrano-de-bergerac-03-030","lineIndex":29,"speaker":"","original":"J'écrirai ma vie en dansant","ipa":"/ʒekʁiʁe ma vi ɑ̃ dɑ̃sɑ̃/","zh":"我以舞步书写生命","en":"I will write my life while dancing","note":"","sourceLineIndex":30},{"id":"cyrano-de-bergerac-03-031","lineIndex":30,"speaker":"","original":"J'en rêve depuis si longtemps","ipa":"/ʒɑ̃ ʁɛv dəpɥi si lɔ̃tɑ̃/","zh":"这梦萦绕多年光阴","en":"I've been dreaming of it for so long","note":"","sourceLineIndex":31},{"id":"cyrano-de-bergerac-03-032","lineIndex":31,"speaker":"","original":"Je danserai, au firmament","ipa":"/ʒə dɑ̃sʁe o fiʁmamɑ̃/","zh":"我将在苍穹起舞","en":"I will dance, in the firmament","note":"","sourceLineIndex":32},{"id":"cyrano-de-bergerac-03-033","lineIndex":32,"speaker":"","original":"Danseuse étoile","ipa":"/dɑ̃søz etwal/","zh":"首席女舞者","en":"Principal dancer","note":"","sourceLineIndex":33},{"id":"cyrano-de-bergerac-03-034","lineIndex":33,"speaker":"","original":"Les salles seront des cathédrales","ipa":"/le sal səʁɔ̃ de katedʁal/","zh":"剧场化作神圣教堂","en":"The halls will be cathedrals","note":"","sourceLineIndex":34},{"id":"cyrano-de-bergerac-03-035","lineIndex":34,"speaker":"","original":"Seule dans la lumière pâle","ipa":"/sœl dɑ̃ la lymjɛʁ pal/","zh":"独舞于苍白光芒","en":"Alone in the pale light","note":"","sourceLineIndex":35},{"id":"cyrano-de-bergerac-03-036","lineIndex":35,"speaker":"","original":"Je danserai","ipa":"/ʒə dɑ̃sʁe/","zh":"我将起舞","en":"I will dance","note":"","sourceLineIndex":36},{"id":"cyrano-de-bergerac-03-037","lineIndex":36,"speaker":"","original":"Sur les étoiles","ipa":"/syʁ lez etwal/","zh":"于星辰之上","en":"On the stars","note":"","sourceLineIndex":37},{"id":"cyrano-de-bergerac-03-038","lineIndex":37,"speaker":"","original":"Danseuse étoile","ipa":"/dɑ̃søz etwal/","zh":"芭蕾舞星","en":"Principal dancer","note":"","sourceLineIndex":38},{"id":"cyrano-de-bergerac-03-039","lineIndex":38,"speaker":"","original":"Bien après le dernier accord","ipa":"/bjɛ̃n apʁɛ lə dɛʁnjeʁ akɔʁ/","zh":"最终音符消散后","en":"Long after the last chord","note":"","sourceLineIndex":39},{"id":"cyrano-de-bergerac-03-040","lineIndex":39,"speaker":"","original":"Les gens applaudiront si fort","ipa":"/le ʒɑ̃ aplodiʁɔ̃ si fɔʁ/","zh":"掌声仍将雷鸣不休","en":"People will applaud so loud","note":"","sourceLineIndex":40},{"id":"cyrano-de-bergerac-03-041","lineIndex":40,"speaker":"","original":"Je danserai, je danserai encore","ipa":"/ʒə dɑ̃sʁe ʒə dɑ̃sʁe ɑ̃kɔʁ/","zh":"我会起舞，继续起舞","en":"I will dance, I will dance again","note":"","sourceLineIndex":41},{"id":"cyrano-de-bergerac-03-042","lineIndex":41,"speaker":"","original":"Danseuse étoile","ipa":"/dɑ̃søz etwal/","zh":"首席女舞者","en":"Principal dancer","note":"","sourceLineIndex":42},{"id":"cyrano-de-bergerac-03-043","lineIndex":42,"speaker":"","original":"Les salles seront des cathédrales","ipa":"/le sal səʁɔ̃ de katedʁal/","zh":"剧场化作神圣教堂","en":"The halls will be cathedrals","note":"","sourceLineIndex":43},{"id":"cyrano-de-bergerac-03-044","lineIndex":43,"speaker":"","original":"Seule dans la lumière pâle","ipa":"/sœl dɑ̃ la lymjɛʁ pal/","zh":"独舞于苍白光芒","en":"Alone in the pale light","note":"","sourceLineIndex":44},{"id":"cyrano-de-bergerac-03-045","lineIndex":44,"speaker":"","original":"Je danserai","ipa":"/ʒə dɑ̃sʁe/","zh":"我将起舞","en":"I will dance","note":"","sourceLineIndex":45},{"id":"cyrano-de-bergerac-03-046","lineIndex":45,"speaker":"","original":"Sur les étoiles","ipa":"/syʁ lez etwal/","zh":"于星辰之上","en":"On the stars","note":"","sourceLineIndex":46},{"id":"cyrano-de-bergerac-03-047","lineIndex":46,"speaker":"","original":"Je danserai","ipa":"/ʒə dɑ̃sʁe/","zh":"我将起舞","en":"I will dance","note":"","sourceLineIndex":47},{"id":"cyrano-de-bergerac-03-048","lineIndex":47,"speaker":"","original":"Sur les étoiles","ipa":"/syʁ lez etwal/","zh":"于星辰之上","en":"On the stars","note":"","sourceLineIndex":48},{"id":"cyrano-de-bergerac-03-049","lineIndex":48,"speaker":"","original":"Je danserai","ipa":"/ʒə dɑ̃sʁe/","zh":"我将起舞","en":"I will dance","note":"","sourceLineIndex":49},{"id":"cyrano-de-bergerac-03-050","lineIndex":49,"speaker":"","original":"Sur les étoiles…","ipa":"/syʁ lez etwal/","zh":"于星辰之上…","en":"On the stars…","note":"","sourceLineIndex":50}],"sourceOrder":3,"displayOrder":3},{"order":4,"id":"04-la-tirade-des-annees","title":"La tirade des années","titleZh":"岁月独白","lines":[{"id":"cyrano-de-bergerac-04-001","lineIndex":1,"speaker":"","original":"Ah non c'est un peu court mon vieux","ipa":"/a nɔ̃ sɛt œ̃ pø kuʁ mɔ̃ vjø/","zh":"啊不，这有点太简短了，老兄","en":"Ah no it's a bit short, old man","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-04-002","lineIndex":2,"speaker":"","original":"On peut dire ma foi, beaucoup mieux","ipa":"/ɔ̃ pø diʁ ma fwa boku mjø/","zh":"说真的，可以写得更好","en":"We can say it, much better","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-04-003","lineIndex":3,"speaker":"","original":"On peut même le chanter...","ipa":"/ɔ̃ pø mɛm lə ʃɑ̃te/","zh":"甚至还能唱出来……","en":"We can even sing it...","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-04-004","lineIndex":4,"speaker":"","original":"tenez, je vais vous le prouver","ipa":"/təne ʒə vɛ vu lə pʁuve/","zh":"听着，我来证明给你看","en":"here, I'll prove it to you","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-04-005","lineIndex":5,"speaker":"","original":"En changeant de style et à chaque couplet","ipa":"/ɑ̃ ʃɑ̃ʒɑ̃ də stil e a ʃak kuplɛ/","zh":"换种风格，每一节都不同","en":"By changing style and with each verse","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-04-006","lineIndex":6,"speaker":"","original":"Roxane vous pouvez les annoncer s'il vous plait?","ipa":"/ʁoksan vu puve lez anɔ̃se sil vu plɛ/","zh":"罗克珊，能麻烦你报一下幕吗？","en":"Roxane, can you announce them please?","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-04-007","lineIndex":7,"speaker":"","original":"Écoutez… je n'sais pas…gardons ce tempo pour commencer?","ipa":"/ekute ʒə nsɛ pa ɡaʁdɔ̃ sə tɑ̃po puʁ kɔmɑ̃se/","zh":"听着…我不知道…先保持这个节奏开始？","en":"Listen... I don't know... let's keep this tempo to start?","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-04-008","lineIndex":8,"speaker":"","original":"Elle préfère l'argent dans vos poches","ipa":"/ɛl pʁefɛʁ laʁʒɑ̃ dɑ̃ vo poʃ/","zh":"她更爱你口袋里的钱","en":"She prefers the money in your pockets","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-04-009","lineIndex":9,"speaker":"","original":"A celle qui se trouve sous vos yeux","ipa":"/a sɛl ki sə tʁuv su voz jø/","zh":"胜过你眼前看到的容颜","en":"To the one in front of your eyes","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-04-010","lineIndex":10,"speaker":"","original":"Quand vous êtes couché elle vous ment","ipa":"/kɑ̃ vuz ɛt kuʃe ɛl vu mɑ̃/","zh":"当你躺下时她对你说谎","en":"When you are in bed she lies to you","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-04-011","lineIndex":11,"speaker":"","original":"Pour se coucher sur... votre testament","ipa":"/puʁ sə kuʃe syʁ votʁ tɛstam/","zh":"只为躺上…你的遗嘱遗产","en":"To lie down on... your will","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-04-012","lineIndex":12,"speaker":"","original":"Maintenant un style plus romantique, par exemple?","ipa":"/mɛ̃tnɑ̃ œ̃ stil ply ʁomɑ̃tik paʁ ɛɡzɑ̃pl/","zh":"现在换个更浪漫的风格，比如？","en":"Now a more romantic style, for example?","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-04-013","lineIndex":13,"speaker":"","original":"Elle est gracieuse comme un printemps","ipa":"/ɛl ɛ ɡʁasjøz kɔm œ̃ pʁɛ̃tɑ̃/","zh":"她如春天般优雅动人","en":"She is graceful like a spring","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-04-014","lineIndex":14,"speaker":"","original":"Une mélodie dans l'air du temps","ipa":"/yn melodi dɑ̃ lɛʁ dy tɑ̃/","zh":"是时代风潮中的旋律轻吟","en":"A melody in tune with the times","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-04-015","lineIndex":15,"speaker":"","original":"Tout seul au bout de votre automne","ipa":"/tu sœl o bu də votʁ otɔn/","zh":"在你暮年的孤独尽头","en":"All alone at the end of your autumn","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-04-016","lineIndex":16,"speaker":"","original":"L'entendrez-vous sans votre sonotone","ipa":"/lɑ̃tɑ̃dʁevu sɑ̃ votʁ sonotɔn/","zh":"没有助听器，可还能听见她的声音？","en":"Will you hear it without your hearing aid","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-04-017","lineIndex":17,"speaker":"","original":"Et une valse, c'est possible?","ipa":"/e yn vals sɛ pɔsibl/","zh":"来首华尔兹，可以吗？","en":"And a waltz, is it possible?","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-04-018","lineIndex":18,"speaker":"","original":"On a beau dire, on a beau faire","ipa":"/ɔ̃n a bo diʁ ɔ̃n a bo fɛʁ/","zh":"任凭你巧舌如簧，任凭你百般花样","en":"No matter what we say, no matter what we do","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-04-019","lineIndex":19,"speaker":"","original":"On a bien l'âge de ses artères","ipa":"/ɔ̃n a bjɛ̃ laʒ də sez aʁtɛʁ/","zh":"血管的年龄从不撒谎","en":"We are as old as our arteries","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-04-020","lineIndex":20,"speaker":"","original":"A trop vouloir valser à l'envers","ipa":"/a tʁo vulwaʁ valse a lɑ̃vɛʁ/","zh":"若执意反向旋转舞步踉跄","en":"Wanting too much to waltz backwards","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-04-021","lineIndex":21,"speaker":"","original":"En trois temps on valse au cimetière","ipa":"/ɑ̃ tʁwa tɑ̃ ɔ̃ vals o simtjɛʁ/","zh":"三拍之后便舞向坟场","en":"In three steps we waltz to the cemetery","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-04-022","lineIndex":22,"speaker":"","original":"Et pour conclure avec panache et avec classe","ipa":"/e puʁ kɔ̃klyʁ avɛk panaʃ e avɛk klas/","zh":"最后要华丽收场，气派张扬","en":"And to conclude with panache and class","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-04-023","lineIndex":23,"speaker":"","original":"A la fin de l'envoi: je casse!","ipa":"/a la fɛ̃ də lɑ̃vwa ʒə kas/","zh":"唱段终了时：我摔杯亮相！","en":"At the end of the sending: I break!","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-04-024","lineIndex":24,"speaker":"","original":"Est-ce que les bougies sont plus chères","ipa":"/ɛs kə le buʒi sɔ̃ ply ʃɛʁ/","zh":"难道蜡烛比你的生日蛋糕","en":"Are candles more expensive","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-04-025","lineIndex":25,"speaker":"","original":"Que votre gâteau d'anniversaire","ipa":"/kə votʁ ɡato danivɛʁsɛʁ/","zh":"还要更加昂贵？","en":"Than your birthday cake","note":"","sourceLineIndex":25},{"id":"cyrano-de-bergerac-04-026","lineIndex":26,"speaker":"","original":"Voilà ce que vous m'auriez dit","ipa":"/vwala sə kə vu moʁje di/","zh":"你若稍有点机智风趣","en":"That's what you would have told me","note":"","sourceLineIndex":26},{"id":"cyrano-de-bergerac-04-027","lineIndex":27,"speaker":"","original":"Avec un peu d'esprit","ipa":"/avɛk œ̃ pø dɛspʁi/","zh":"本可对我说出这番妙语","en":"With a little wit","note":"","sourceLineIndex":27},{"id":"cyrano-de-bergerac-04-028","lineIndex":28,"speaker":"","original":"Mais vous n'en avez pas","ipa":"/mɛ vu nɑ̃n ave pa/","zh":"可惜你半点没有","en":"But you don't have any","note":"","sourceLineIndex":28},{"id":"cyrano-de-bergerac-04-029","lineIndex":29,"speaker":"","original":"Et quand bien même","ipa":"/e kɑ̃ bjɛ̃ mɛm/","zh":"即便如此","en":"And even so","note":"","sourceLineIndex":29},{"id":"cyrano-de-bergerac-04-030","lineIndex":30,"speaker":"","original":"Ce qui se dit de moi","ipa":"/sə ki sə di də mwa/","zh":"那些关于我的流言蜚语","en":"What is said about me","note":"","sourceLineIndex":30},{"id":"cyrano-de-bergerac-04-031","lineIndex":31,"speaker":"","original":"Je me le sers moi-même","ipa":"/ʒə mə lə sɛʁ mwamɛm/","zh":"我亲自为自己盛取","en":"I use it myself","note":"","sourceLineIndex":31}],"sourceOrder":4,"displayOrder":4},{"order":5,"id":"05-je-viens-a-toi","title":"Je viens à toi","titleZh":"我奔向你","lines":[{"id":"cyrano-de-bergerac-05-001","lineIndex":1,"speaker":"","original":"Seul sur la scène dans la lumière","ipa":"/sœl syʁ la sɛn dɑ̃ la lymjɛʁ/","zh":"独自站在舞台的光晕中","en":"Alone on the stage in the light","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-05-002","lineIndex":2,"speaker":"","original":"Pour vous, je me donne je me perds","ipa":"/puʁ vu ʒə mə dɔn ʒə mə pɛʁ/","zh":"为你 我献出自己 也迷失自己","en":"For you, I give myself I lose myself","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-05-003","lineIndex":3,"speaker":"","original":"A chercher ma voix chaque soir","ipa":"/a ʃɛʁʃe ma vwa ʃak swaʁ/","zh":"每夜追寻着属于我的声音","en":"Searching for my voice every evening","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-05-004","lineIndex":4,"speaker":"","original":"Sauras-tu voir?","ipa":"/soʁaty vwaʁ/","zh":"你能否看清","en":"Will you be able to see?","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-05-005","lineIndex":5,"speaker":"","original":"Plus loin derrière les apparences","ipa":"/ply lwɛ̃ dɛʁjɛʁ lez apaʁɑ̃s/","zh":"在表象的更深处","en":"Further behind appearances","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-05-006","lineIndex":6,"speaker":"","original":"Les couleurs, les nuances de mes silences","ipa":"/le kulœʁ le nyɑ̃s də me silɑ̃s/","zh":"我沉默中蕴藏的色彩与层次","en":"The colors, the nuances of my silences","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-05-007","lineIndex":7,"speaker":"","original":"A qui je pense seul dans le noir","ipa":"/a ki ʒə pɑ̃s sœl dɑ̃ lə nwaʁ/","zh":"黑暗中独处时我在思念谁","en":"Who I think about alone in the dark","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-05-008","lineIndex":8,"speaker":"","original":"Va savoir","ipa":"/va savwaʁ/","zh":"天知道呢","en":"Who knows","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-05-009","lineIndex":9,"speaker":"","original":"Et du plus profond de mes doutes","ipa":"/e dy ply pʁofɔ̃ də me dut/","zh":"从我疑虑的最深渊","en":"And from the depths of my doubts","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-05-010","lineIndex":10,"speaker":"","original":"Au plus fort de tous mes combats","ipa":"/o ply fɔʁ də tu me kɔ̃ba/","zh":"到我所有战斗的最前线","en":"At the strongest of all my fights","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-05-011","lineIndex":11,"speaker":"","original":"Si je m'égare sur d'autres routes","ipa":"/si ʒə meɡaʁ syʁ dotʁ ʁut/","zh":"即使我在其他路上彷徨","en":"If I stray onto other roads","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-05-012","lineIndex":12,"speaker":"","original":"Tous les chemins me mènent à toi","ipa":"/tu le ʃəmɛ̃ mə mɛnt a twa/","zh":"所有路途都引我向你","en":"All paths lead me to you","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-05-013","lineIndex":13,"speaker":"","original":"Tu connais déjà mes sourires","ipa":"/ty kɔnɛ deʒa me suʁiʁ/","zh":"你早已熟悉我的笑容","en":"You already know my smiles","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-05-014","lineIndex":14,"speaker":"","original":"Mais dis-moi, comment pouvoir t'offrir","ipa":"/mɛ dimwa kɔmɑ̃ puvwaʁ tɔfʁiʁ/","zh":"但请告诉我 如何才能向你展现","en":"But tell me, how can I offer you","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-05-015","lineIndex":15,"speaker":"","original":"L'envers de la vie que je cache","ipa":"/lɑ̃vɛʁ də la vi kə ʒə kaʃ/","zh":"我隐藏的生命背面","en":"The other side of life that I hide","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-05-016","lineIndex":16,"speaker":"","original":"Que tu saches","ipa":"/kə ty saʃ/","zh":"愿你知道","en":"That you know","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-05-017","lineIndex":17,"speaker":"","original":"Que dans la pâleur de mes nuits","ipa":"/kə dɑ̃ la palœʁ də me nɥi/","zh":"在我苍白的夜色里","en":"That in the paleness of my nights","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-05-018","lineIndex":18,"speaker":"","original":"Tout seul, c'est pour toi, pour toi que j'écris","ipa":"/tu sœl sɛ puʁ twa puʁ twa kə ʒekʁi/","zh":"孤独中 我书写的一切都是为你 为你","en":"All alone, it is for you, for you that I write","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-05-019","lineIndex":19,"speaker":"","original":"Pour toi que je ne connais pas","ipa":"/puʁ twa kə ʒə nə kɔnɛ pa/","zh":"为我不认识的你","en":"For you whom I do not know","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-05-020","lineIndex":20,"speaker":"","original":"Qui que tu sois","ipa":"/ki kə ty swa/","zh":"无论你是谁","en":"Whoever you are","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-05-021","lineIndex":21,"speaker":"","original":"Mais du plus profond de mes doutes","ipa":"/mɛ dy ply pʁofɔ̃ də me dut/","zh":"从我疑虑的最深渊","en":"But from the depths of my doubts","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-05-022","lineIndex":22,"speaker":"","original":"Au plus fort de tous mes combats","ipa":"/o ply fɔʁ də tu me kɔ̃ba/","zh":"到我所有战斗的最前线","en":"At the strongest of all my fights","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-05-023","lineIndex":23,"speaker":"","original":"Si je m'égare sur d'autres routes","ipa":"/si ʒə meɡaʁ syʁ dotʁ ʁut/","zh":"即使我在其他路上彷徨","en":"If I stray onto other roads","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-05-024","lineIndex":24,"speaker":"","original":"Tous les chemins me mènent à toi","ipa":"/tu le ʃəmɛ̃ mə mɛnt a twa/","zh":"所有路途都引我向你","en":"All paths lead me to you","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-05-025","lineIndex":25,"speaker":"","original":"J'irai au bout du temps qui passe","ipa":"/ʒiʁe o bu dy tɑ̃ ki pas/","zh":"我将走到流逝时光的尽头","en":"I will go to the end of the time that passes","note":"","sourceLineIndex":25},{"id":"cyrano-de-bergerac-05-026","lineIndex":26,"speaker":"","original":"Pour toi… où que tu sois… qui que tu sois","ipa":"/puʁ twa u kə ty swa ki kə ty swa/","zh":"为你…无论你在哪里…无论你是谁","en":"For you... wherever you are... whoever you are","note":"","sourceLineIndex":26},{"id":"cyrano-de-bergerac-05-027","lineIndex":27,"speaker":"","original":"Et du plus profond de mes doutes","ipa":"/e dy ply pʁofɔ̃ də me dut/","zh":"从我疑虑的最深渊","en":"And from the depths of my doubts","note":"","sourceLineIndex":27},{"id":"cyrano-de-bergerac-05-028","lineIndex":28,"speaker":"","original":"Au plus fort de tous mes combats","ipa":"/o ply fɔʁ də tu me kɔ̃ba/","zh":"到我所有战斗的最前线","en":"At the strongest of all my fights","note":"","sourceLineIndex":28},{"id":"cyrano-de-bergerac-05-029","lineIndex":29,"speaker":"","original":"Si je m'égare sur d'autres routes","ipa":"/si ʒə meɡaʁ syʁ dotʁ ʁut/","zh":"即使我在其他路上彷徨","en":"If I stray onto other roads","note":"","sourceLineIndex":29},{"id":"cyrano-de-bergerac-05-030","lineIndex":30,"speaker":"","original":"Tous les chemins me mènent à toi…","ipa":"/tu le ʃəmɛ̃ mə mɛnt a twa/","zh":"所有路途都引我向你…","en":"All roads lead me to you...","note":"","sourceLineIndex":30},{"id":"cyrano-de-bergerac-05-031","lineIndex":31,"speaker":"","original":"J'en ai fini de mes déroutes","ipa":"/ʒɑ̃n e fini də me deʁut/","zh":"我已结束我的迷途","en":"I'm done with my detours","note":"","sourceLineIndex":31},{"id":"cyrano-de-bergerac-05-032","lineIndex":32,"speaker":"","original":"Écoute... Je viens à toi","ipa":"/ekut ʒə vjɛ̃z a twa/","zh":"听啊…我正朝你走来","en":"Listen... I'm coming to you","note":"","sourceLineIndex":32}],"sourceOrder":5,"displayOrder":5},{"order":6,"id":"06-un-autre-paradis","title":"Un autre paradis","titleZh":"另一座天堂","lines":[{"id":"cyrano-de-bergerac-06-001","lineIndex":1,"speaker":"","original":"On se voit, on s'évite","ipa":"/ɔ̃ sə vwa ɔ̃ sevit/","zh":"我们相见，又彼此躲闪","en":"We see each other, we avoid each other","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-06-002","lineIndex":2,"speaker":"","original":"On se veut, on hésite","ipa":"/ɔ̃ sə vø ɔ̃n ezit/","zh":"我们渴望，却犹豫不安","en":"We want each other, we hesitate","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-06-003","lineIndex":3,"speaker":"","original":"Mais le temps va trop vite","ipa":"/mɛ lə tɑ̃ va tʁo vit/","zh":"可时光流逝得太快","en":"But time goes too quickly","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-06-004","lineIndex":4,"speaker":"","original":"Sans écrire une suite","ipa":"/sɑ̃z ekʁiʁ yn sɥit/","zh":"来不及写下续篇","en":"Without writing a sequel","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-06-005","lineIndex":5,"speaker":"","original":"On se quitte… déjà, on se quitte","ipa":"/ɔ̃ sə kit deʒa ɔ̃ sə kit/","zh":"我们分离…转眼，就已分离","en":"We leave each other... already, we leave each other","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-06-006","lineIndex":6,"speaker":"","original":"Un regard, par hasard","ipa":"/œ̃ ʁəɡaʁ paʁ azaʁ/","zh":"一次偶然的凝望","en":"A look, by chance","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-06-007","lineIndex":7,"speaker":"","original":"Un sourire, ne rien dire","ipa":"/œ̃ suʁiʁ nə ʁjɛ̃ diʁ/","zh":"一抹微笑，无须多言","en":"A smile, say nothing","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-06-008","lineIndex":8,"speaker":"","original":"Et déjà tout savoir, sans avoir un espoir","ipa":"/e deʒa tu savwaʁ sɑ̃z avwaʁ œ̃n ɛspwaʁ/","zh":"便已了然一切，不抱任何希望","en":"And already know everything, without having a hope","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-06-009","lineIndex":9,"speaker":"","original":"De se revoir","ipa":"/də sə ʁəvwaʁ/","zh":"能重逢相见","en":"To see each other again","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-06-010","lineIndex":10,"speaker":"","original":"De te revoir","ipa":"/də tə ʁəvwaʁ/","zh":"与你重逢","en":"To see you again","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-06-011","lineIndex":11,"speaker":"","original":"Peut-être une autre fois","ipa":"/pøtɛtʁ yn otʁ fwa/","zh":"或许在另一个时刻","en":"Maybe another time","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-06-012","lineIndex":12,"speaker":"","original":"Peut-être une autre vie","ipa":"/pøtɛtʁ yn otʁ vi/","zh":"或许在另一段人生","en":"Maybe another life","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-06-013","lineIndex":13,"speaker":"","original":"Peut-être un autre toi et moi","ipa":"/pøtɛtʁ œ̃n otʁ twa e mwa/","zh":"或许是另一对我和你","en":"Maybe another you and me","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-06-014","lineIndex":14,"speaker":"","original":"Pour s'offrir un bout d'paradis","ipa":"/puʁ sɔfʁiʁ œ̃ bu dpaʁadi/","zh":"去撷取一小片天堂","en":"To treat yourself to a piece of paradise","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-06-015","lineIndex":15,"speaker":"","original":"Peut-être un autre ciel","ipa":"/pøtɛtʁ œ̃n otʁ sjɛl/","zh":"或许是另一片天空","en":"Perhaps another sky","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-06-016","lineIndex":16,"speaker":"","original":"Un regard parallèle","ipa":"/œ̃ ʁəɡaʁ paʁalɛl/","zh":"一次平行的凝望","en":"A parallel look","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-06-017","lineIndex":17,"speaker":"","original":"Et voir nos deux vies qui chancellent","ipa":"/e vwaʁ no dø vi ki ʃɑ̃sɛl/","zh":"看我们的人生摇晃不定","en":"And see our two lives faltering","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-06-018","lineIndex":18,"speaker":"","original":"Puisque l'amour est un duel","ipa":"/pɥiskə lamuʁ ɛt œ̃ dyɛl/","zh":"因为爱本就是一场较量","en":"Since love is a duel","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-06-019","lineIndex":19,"speaker":"","original":"Un instant, juste un instant","ipa":"/œ̃n ɛ̃stɑ̃ ʒyst œ̃n ɛ̃stɑ̃/","zh":"一瞬间，仅仅一瞬间","en":"One moment, just one moment","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-06-020","lineIndex":20,"speaker":"","original":"S'éblouir, ne plus mentir","ipa":"/seblwiʁ nə ply mɑ̃tiʁ/","zh":"目眩神迷，不再伪装","en":"To be dazzled, to no longer lie","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-06-021","lineIndex":21,"speaker":"","original":"Et pouvoir tout se dire","ipa":"/e puvwaʁ tu sə diʁ/","zh":"得以倾诉所有衷肠","en":"And to be able to tell each other everything","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-06-022","lineIndex":22,"speaker":"","original":"Voir sa vie qui chavire","ipa":"/vwaʁ sa vi ki ʃaviʁ/","zh":"看人生在","en":"To see one's life turn upside down","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-06-023","lineIndex":23,"speaker":"","original":"Dans un sourire…","ipa":"/dɑ̃z œ̃ suʁiʁ/","zh":"微笑中倾覆…","en":"In a smile…","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-06-024","lineIndex":24,"speaker":"","original":"Dans ton sourire","ipa":"/dɑ̃ tɔ̃ suʁiʁ/","zh":"在你的微笑中","en":"In your smile","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-06-025","lineIndex":25,"speaker":"","original":"Peut-être une autre fois","ipa":"/pøtɛtʁ yn otʁ fwa/","zh":"或许在另一个时刻","en":"Maybe another time","note":"","sourceLineIndex":25},{"id":"cyrano-de-bergerac-06-026","lineIndex":26,"speaker":"","original":"Peut-être une autre vie","ipa":"/pøtɛtʁ yn otʁ vi/","zh":"或许在另一段人生","en":"Maybe another life","note":"","sourceLineIndex":26},{"id":"cyrano-de-bergerac-06-027","lineIndex":27,"speaker":"","original":"Peut-être un autre toi et moi","ipa":"/pøtɛtʁ œ̃n otʁ twa e mwa/","zh":"或许是另一对我和你","en":"Maybe another you and me","note":"","sourceLineIndex":27},{"id":"cyrano-de-bergerac-06-028","lineIndex":28,"speaker":"","original":"Pour s'offrir un bout d'paradis","ipa":"/puʁ sɔfʁiʁ œ̃ bu dpaʁadi/","zh":"去撷取一小片天堂","en":"To treat yourself to a piece of paradise","note":"","sourceLineIndex":28},{"id":"cyrano-de-bergerac-06-029","lineIndex":29,"speaker":"","original":"Peut-être un autre ciel","ipa":"/pøtɛtʁ œ̃n otʁ sjɛl/","zh":"或许是另一片天空","en":"Perhaps another sky","note":"","sourceLineIndex":29},{"id":"cyrano-de-bergerac-06-030","lineIndex":30,"speaker":"","original":"Un regard parallèle","ipa":"/œ̃ ʁəɡaʁ paʁalɛl/","zh":"一次平行的凝望","en":"A parallel look","note":"","sourceLineIndex":30},{"id":"cyrano-de-bergerac-06-031","lineIndex":31,"speaker":"","original":"Et voir nos deux vies qui chancellent","ipa":"/e vwaʁ no dø vi ki ʃɑ̃sɛl/","zh":"看我们的人生摇晃不定","en":"And see our two lives faltering","note":"","sourceLineIndex":31},{"id":"cyrano-de-bergerac-06-032","lineIndex":32,"speaker":"","original":"Puisque l'amour est un duel","ipa":"/pɥiskə lamuʁ ɛt œ̃ dyɛl/","zh":"因为爱本就是一场较量","en":"Since love is a duel","note":"","sourceLineIndex":32},{"id":"cyrano-de-bergerac-06-033","lineIndex":33,"speaker":"","original":"Peut-être une autre vie","ipa":"/pøtɛtʁ yn otʁ vi/","zh":"或许另一段人生","en":"Maybe another life","note":"","sourceLineIndex":33},{"id":"cyrano-de-bergerac-06-034","lineIndex":34,"speaker":"","original":"Un autre paradis","ipa":"/œ̃n otʁ paʁadi/","zh":"另一座天堂","en":"Another paradise","note":"","sourceLineIndex":34},{"id":"cyrano-de-bergerac-06-035","lineIndex":35,"speaker":"","original":"Peut-être une autre fois","ipa":"/pøtɛtʁ yn otʁ fwa/","zh":"或许另一个时刻","en":"Maybe another time","note":"","sourceLineIndex":35},{"id":"cyrano-de-bergerac-06-036","lineIndex":36,"speaker":"","original":"Peut-être une autre vie","ipa":"/pøtɛtʁ yn otʁ vi/","zh":"或许另一段人生","en":"Maybe another life","note":"","sourceLineIndex":36},{"id":"cyrano-de-bergerac-06-037","lineIndex":37,"speaker":"","original":"Peut-être un autre toi","ipa":"/pøtɛtʁ œ̃n otʁ twa/","zh":"或许另一个你","en":"Maybe another you","note":"","sourceLineIndex":37},{"id":"cyrano-de-bergerac-06-038","lineIndex":38,"speaker":"","original":"Peut-être un autre moi","ipa":"/pøtɛtʁ œ̃n otʁ mwa/","zh":"或许另一个我","en":"Maybe another me","note":"","sourceLineIndex":38},{"id":"cyrano-de-bergerac-06-039","lineIndex":39,"speaker":"","original":"Un autre paradis","ipa":"/œ̃n otʁ paʁadi/","zh":"另一座天堂","en":"Another paradise","note":"","sourceLineIndex":39}],"sourceOrder":6,"displayOrder":6},{"order":7,"id":"07-juste-lui","title":"Juste lui","titleZh":"只有他","lines":[{"id":"cyrano-de-bergerac-07-001","lineIndex":1,"speaker":"","original":"Le rideau s'est levé, tout me semblait possible","ipa":"/lə ʁido sɛ ləve tu mə sɑ̃blɛ pɔsibl/","zh":"帷幕升起 一切皆有可能","en":"The curtain rose, everything seemed possible","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-07-002","lineIndex":2,"speaker":"","original":"Comme pour un rendez-vous, une première fois","ipa":"/kɔm puʁ œ̃ ʁɑ̃devu yn pʁəmjɛʁ fwa/","zh":"好似初次赴约的悸动","en":"As for a date, a first time","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-07-003","lineIndex":3,"speaker":"","original":"J'avais au fond de moi, cette force invisible","ipa":"/ʒavɛz o fɔ̃ də mwa sɛt fɔʁs ɛ̃vizibl/","zh":"我心底涌动着无形的力量","en":"Deep inside me, this invisible force","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-07-004","lineIndex":4,"speaker":"","original":"Qui agrandit le cœur et écarte les bras","ipa":"/ki aɡʁɑ̃di lə kœʁ e ekaʁt le bʁa/","zh":"它让胸怀开阔 让双臂舒展","en":"Who enlarges the heart and spreads the arms","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-07-005","lineIndex":5,"speaker":"","original":"Et quand il a chanté, je connaissais sa voix","ipa":"/e kɑ̃t il a ʃɑ̃te ʒə kɔnɛsɛ sa vwa/","zh":"当他开口歌唱 我熟悉那声音","en":"And when he sang, I knew his voice","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-07-006","lineIndex":6,"speaker":"","original":"J'ai reconnu ses mots, jusque dans ses silences","ipa":"/ʒe ʁəkɔny se mo ʒysk dɑ̃ se silɑ̃s/","zh":"甚至在他的静默中 我辨认出字句","en":"I recognized his words, even in his silences","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-07-007","lineIndex":7,"speaker":"","original":"J'étais seule dans la foule, et il chantait pour moi","ipa":"/ʒetɛ sœl dɑ̃ la ful e il ʃɑ̃tɛ puʁ mwa/","zh":"人潮汹涌唯我独立 而他正为我歌唱","en":"I was alone in the crowd, and he sang for me","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-07-008","lineIndex":8,"speaker":"","original":"C'était comme un aveu, une confidence","ipa":"/setɛ kɔm œ̃n avø yn kɔ̃fidɑ̃s/","zh":"如同告白 又似私语","en":"It was like a confession, a confidence","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-07-009","lineIndex":9,"speaker":"","original":"Et c'est lui, juste lui","ipa":"/e sɛ lɥi ʒyst lɥi/","zh":"是他 他","en":"And it's him, just him","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-07-010","lineIndex":10,"speaker":"","original":"La scène s'est allumée, nos yeux se sont croisés","ipa":"/la sɛn sɛt alyme noz jø sə sɔ̃ kʁwaze/","zh":"舞台亮起 目光交汇","en":"The stage lit up, our eyes met","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-07-011","lineIndex":11,"speaker":"","original":"Un regard c'est trop court pour tout se raconter","ipa":"/œ̃ ʁəɡaʁ sɛ tʁo kuʁ puʁ tu sə ʁakɔ̃te/","zh":"一瞥眼太短暂 诉不尽万语千言","en":"One look is too short to tell everything","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-07-012","lineIndex":12,"speaker":"","original":"Je le connais à peine mais je le connaissais","ipa":"/ʒə lə kɔnɛz a pɛn mɛ ʒə lə kɔnɛsɛ/","zh":"我对他知之甚少 却又早已相知","en":"I barely know him but I knew him","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-07-013","lineIndex":13,"speaker":"","original":"J'ai toujours eu en moi celui que je voulais","ipa":"/ʒe tuʒuʁz y ɑ̃ mwa səlɥi kə ʒə vulɛ/","zh":"我心中始终留存着我想的那个他","en":"I always had in me the one I wanted","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-07-014","lineIndex":14,"speaker":"","original":"Et c'est lui, juste lui","ipa":"/e sɛ lɥi ʒyst lɥi/","zh":"是他 只有他","en":"And it's him, just him","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-07-015","lineIndex":15,"speaker":"","original":"Alors je veux y croire","ipa":"/alɔʁ ʒə vøz i kʁwaʁ/","zh":"我愿相信这一切","en":"So I want to believe","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-07-016","lineIndex":16,"speaker":"","original":"Je veux serrer les poings","ipa":"/ʒə vø sɛʁe le pwɛ̃/","zh":"我愿攥紧双拳","en":"I want to clench my fists","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-07-017","lineIndex":17,"speaker":"","original":"Remercier le hasard","ipa":"/ʁəmɛʁsje lə azaʁ/","zh":"感谢这偶然的际遇","en":"Thank chance","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-07-018","lineIndex":18,"speaker":"","original":"Et forcer le destin","ipa":"/e fɔʁse lə dɛstɛ̃/","zh":"并扭转命运的轨迹","en":"And force destiny","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-07-019","lineIndex":19,"speaker":"","original":"Je veux le voir ce soir","ipa":"/ʒə vø lə vwaʁ sə swaʁ/","zh":"今夜我想见他","en":"I want to see him tonight","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-07-020","lineIndex":20,"speaker":"","original":"Je veux le voir demain","ipa":"/ʒə vø lə vwaʁ dəmɛ̃/","zh":"明日亦想重逢","en":"I want to see him tomorrow","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-07-021","lineIndex":21,"speaker":"","original":"Que plus rien ne sépare","ipa":"/kə ply ʁjɛ̃ nə sepaʁ/","zh":"再不让任何事物阻隔","en":"Let nothing separate","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-07-022","lineIndex":22,"speaker":"","original":"Les lignes de nos mains","ipa":"/le linj də no mɛ̃/","zh":"让掌纹紧密相连","en":"The lines of our hands","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-07-023","lineIndex":23,"speaker":"","original":"Les lignes de nos mains","ipa":"/le linj də no mɛ̃/","zh":"让我们永远相牵","en":"The lines of our hands","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-07-024","lineIndex":24,"speaker":"","original":"Le rideau est tombé, tout me semble possible","ipa":"/lə ʁido ɛ tɔ̃be tu mə sɑ̃bl pɔsibl/","zh":"帷幕落下 一切皆有可能","en":"The curtain has fallen, everything seems possible","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-07-025","lineIndex":25,"speaker":"","original":"Je n'attends plus personne, et je sais qu'il m'attend","ipa":"/ʒə natɑ̃ ply pɛʁsɔn e ʒə sɛ kil matɑ̃/","zh":"我不再等待任何人 却知他在等候我","en":"I no longer wait for anyone, and I know he's waiting for me","note":"","sourceLineIndex":25},{"id":"cyrano-de-bergerac-07-026","lineIndex":26,"speaker":"","original":"Il viendra guidé par cette force invisible","ipa":"/il vjɛ̃dʁa ɡide paʁ sɛt fɔʁs ɛ̃vizibl/","zh":"他将被无形力量指引而来","en":"He will come, guided by this invisible force","note":"","sourceLineIndex":26},{"id":"cyrano-de-bergerac-07-027","lineIndex":27,"speaker":"","original":"Parce que je suis Roxane et que j'aime Christian","ipa":"/paʁskə ʒə sɥi ʁoksan e kə ʒɛm kʁistjɑ̃/","zh":"因为我是 Roxane 而我爱着Christian","en":"Because I am Roxane and I love Christian","note":"","sourceLineIndex":27},{"id":"cyrano-de-bergerac-07-028","lineIndex":28,"speaker":"","original":"Et c'est lui... juste lui... Et c'est lui... juste lui...","ipa":"/e sɛ lɥi ʒyst lɥi e sɛ lɥi ʒyst lɥi/","zh":"是他...正是他...是他...只有他...","en":"And it's him... just him... And it's him... just him...","note":"","sourceLineIndex":28}],"sourceOrder":7,"displayOrder":7},{"order":8,"id":"08-il-est-toujours-trop-tard","title":"Il est toujours trop tard","titleZh":"唯有太迟","lines":[{"id":"cyrano-de-bergerac-08-001","lineIndex":1,"speaker":"","original":"Elle est encore au printemps","ipa":"/ɛl ɛt ɑ̃kɔʁ o pʁɛ̃tɑ̃/","zh":"春还为她停驻","en":"It's still spring","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-08-002","lineIndex":2,"speaker":"","original":"Et je suis en automne","ipa":"/e ʒə sɥiz ɑ̃n otɔn/","zh":"秋已把我裹挟","en":"And I am in autumn","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-08-003","lineIndex":3,"speaker":"","original":"Son avenir est si grand","ipa":"/sɔ̃n avniʁ ɛ si ɡʁɑ̃/","zh":"她的未来海阔天空","en":"Her future is so great","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-08-004","lineIndex":4,"speaker":"","original":"Le soleil m'abandonne","ipa":"/lə solɛj mabɑ̃dɔn/","zh":"而我已是日薄西山","en":"The sun abandons me","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-08-005","lineIndex":5,"speaker":"","original":"Ses espoirs se noieront aux rives de l'avenir","ipa":"/sez ɛspwaʁ sə nwaʁɔ̃t o ʁiv də lavniʁ/","zh":"希冀终将淹溺在来日之岸","en":"Its hopes will drown on the shores of the future","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-08-006","lineIndex":6,"speaker":"","original":"Et tout ce qui chantait lui semblera gémir","ipa":"/e tu sə ki ʃɑ̃tɛ lɥi sɑ̃bləʁa ʒemiʁ/","zh":"往日的欢歌也将化作呻吟","en":"And everything that sang will seem to moan","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-08-007","lineIndex":7,"speaker":"","original":"Elle verra sous mes rides ce que je ne suis plus","ipa":"/ɛl vɛʁa su me ʁid sə kə ʒə nə sɥi ply/","zh":"她将在皱纹下窥见我不复的过往","en":"She will see beneath my wrinkles what I no longer am","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-08-008","lineIndex":8,"speaker":"","original":"La pâleur livide d'un intime inconnu","ipa":"/la palœʁ livid dœ̃n ɛ̃tim ɛ̃kɔny/","zh":"一个亲密又陌生的苍白面容","en":"The livid pallor of an intimate stranger","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-08-009","lineIndex":9,"speaker":"","original":"D'un inconnu","ipa":"/dœ̃n ɛ̃kɔny/","zh":"一个陌生人","en":"Of a stranger","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-08-010","lineIndex":10,"speaker":"","original":"Il est déjà trop tard…","ipa":"/il ɛ deʒa tʁo taʁ/","zh":"为时已太迟","en":"It is already too late...","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-08-011","lineIndex":11,"speaker":"","original":"Elle est encore au printemps","ipa":"/ɛl ɛt ɑ̃kɔʁ o pʁɛ̃tɑ̃/","zh":"春还为她停驻","en":"It's still spring","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-08-012","lineIndex":12,"speaker":"","original":"Et je suis en automne","ipa":"/e ʒə sɥiz ɑ̃n otɔn/","zh":"秋已把我裹挟","en":"And I am in autumn","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-08-013","lineIndex":13,"speaker":"","original":"Son avenir est si grand","ipa":"/sɔ̃n avniʁ ɛ si ɡʁɑ̃/","zh":"她的未来海阔天空","en":"Her future is so great","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-08-014","lineIndex":14,"speaker":"","original":"Le soleil m'abandonne","ipa":"/lə solɛj mabɑ̃dɔn/","zh":"而我已是日薄西山","en":"The sun abandons me","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-08-015","lineIndex":15,"speaker":"","original":"Elle cherchera en vain ce qu'étaient ses espoirs","ipa":"/ɛl ʃɛʁʃʁa ɑ̃ vɛ̃ sə ketɛ sez ɛspwaʁ/","zh":"她将徒劳地寻找曾经的希冀","en":"She will search in vain for what her hopes were","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-08-016","lineIndex":16,"speaker":"","original":"Dans les yeux résignés d'une moitié de vieillard","ipa":"/dɑ̃ lez jø ʁezinje dyn mwatje də vjɛjaʁ/","zh":"在一个听天由命的老人眼中","en":"In the resigned eyes of half an old man","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-08-017","lineIndex":17,"speaker":"","original":"Et l'automne passera et l'été et l'hiver","ipa":"/e lotɔn pasʁa e lete e livɛʁ/","zh":"秋日将逝 何况冬夏","en":"And autumn will pass and summer and winter","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-08-018","lineIndex":18,"speaker":"","original":"Elle ne verra en moi que le temps qui se perd","ipa":"/ɛl nə vɛʁa ɑ̃ mwa kə lə tɑ̃ ki sə pɛʁ/","zh":"她在我身上只会看到年华似水","en":"She will only see in me the time that is wasted","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-08-019","lineIndex":19,"speaker":"","original":"Que le temps qui se perd","ipa":"/kə lə tɑ̃ ki sə pɛʁ/","zh":"一去不再回","en":"Only the time that is lost","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-08-020","lineIndex":20,"speaker":"","original":"Il est déjà trop tard…","ipa":"/il ɛ deʒa tʁo taʁ/","zh":"为时已太迟","en":"It is already too late...","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-08-021","lineIndex":21,"speaker":"","original":"Elle est encore au printemps","ipa":"/ɛl ɛt ɑ̃kɔʁ o pʁɛ̃tɑ̃/","zh":"春还为她停驻","en":"It's still spring","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-08-022","lineIndex":22,"speaker":"","original":"Et je suis en automne","ipa":"/e ʒə sɥiz ɑ̃n otɔn/","zh":"秋已把我裹挟","en":"And I am in autumn","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-08-023","lineIndex":23,"speaker":"","original":"Son avenir est si grand","ipa":"/sɔ̃n avniʁ ɛ si ɡʁɑ̃/","zh":"她的未来海阔天空","en":"Her future is so great","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-08-024","lineIndex":24,"speaker":"","original":"Le soleil m'abandonne","ipa":"/lə solɛj mabɑ̃dɔn/","zh":"而我已是日薄西山","en":"The sun abandons me","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-08-025","lineIndex":25,"speaker":"","original":"Il est déjà trop tard… Il est","ipa":"/il ɛ deʒa tʁo taʁ il ɛ/","zh":"为时已太迟 为时","en":"It is already too late... It is","note":"","sourceLineIndex":25},{"id":"cyrano-de-bergerac-08-026","lineIndex":26,"speaker":"","original":"toujours trop tard","ipa":"/tuʒuʁ tʁo taʁ/","zh":"唯有太迟","en":"always too late","note":"","sourceLineIndex":26},{"id":"cyrano-de-bergerac-08-027","lineIndex":27,"speaker":"","original":"Je sais bien que le printemps","ipa":"/ʒə sɛ bjɛ̃ kə lə pʁɛ̃tɑ̃/","zh":"我深知那春光","en":"I know that spring","note":"","sourceLineIndex":27},{"id":"cyrano-de-bergerac-08-028","lineIndex":28,"speaker":"","original":"Ne fleurit jamais en automne","ipa":"/nə fløʁi ʒamɛz ɑ̃n otɔn/","zh":"不会在秋日盛放","en":"Never blooms in autumn","note":"","sourceLineIndex":28},{"id":"cyrano-de-bergerac-08-029","lineIndex":29,"speaker":"","original":"L'amour n'efface pas le temps","ipa":"/lamuʁ nefas pa lə tɑ̃/","zh":"爱情抹不去时光","en":"Love does not erase time","note":"","sourceLineIndex":29},{"id":"cyrano-de-bergerac-08-030","lineIndex":30,"speaker":"","original":"Le soleil m'abandonne","ipa":"/lə solɛj mabɑ̃dɔn/","zh":"我已是日薄西山","en":"The sun abandons me","note":"","sourceLineIndex":30}],"sourceOrder":8,"displayOrder":8},{"order":9,"id":"09-je-connais-la-chanson","title":"Je connais la chanson","titleZh":"我熟悉这首歌","lines":[{"id":"cyrano-de-bergerac-09-001","lineIndex":1,"speaker":"","original":"Je suis dans l'show business, enfin j'dirai dans l'business","ipa":"/ʒə sɥi dɑ̃ ɛlʃəʊ bɪznəs ɑ̃fɛ̃ ʒdiʁe dɑ̃ ɛlbɪznəs/","zh":"我混迹娱乐圈，更准确说是商业圈","en":"I'm in show business, well I'll say in business","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-09-002","lineIndex":2,"speaker":"","original":"J'ai pas l'amour de l'art surtout celui des dollars","ipa":"/ʒe pa lamuʁ də laʁ syʁtu səlɥi de dɔlaʁ/","zh":"我追求的不是艺术热爱，尤其是美元艺术","en":"I don't have a love of art, especially dollars","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-09-003","lineIndex":3,"speaker":"","original":"Mais pour trouver une star j'vous explique pas mon stress","ipa":"/mɛ puʁ tʁuve yn staʁ ʒvuz ɛksplik pa mɔ̃ stɹɛs/","zh":"但为了发掘明星，我承受的压力无需多言","en":"But to find a star I can't explain my stress","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-09-004","lineIndex":4,"speaker":"","original":"Tout c'que j'dois m'infuser en fumant mon cigare","ipa":"/tu skə ʒdwa mɛ̃fyze ɑ̃ fymɑ̃ mɔ̃ siɡaʁ/","zh":"所有需要思考的事都在抽雪茄时浸入脑海","en":"All that I have to infuse myself while smoking my cigar","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-09-005","lineIndex":5,"speaker":"","original":"Divas d'la variété ou des chanteuses bretonnes","ipa":"/diva dla vaʁjete u de ʃɑ̃tøz bʁətɔn/","zh":"流行乐坛的耀眼歌后或布列塔尼民谣歌手","en":"Divas variety or Breton singers","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-09-006","lineIndex":6,"speaker":"","original":"Des rappeurs illettrés, des poètes africains","ipa":"/de ʁapœʁz ilɛtʁe de pɔɛtz afʁikɛ̃/","zh":"不识字的饶舌艺人，非洲诗人","en":"Illiterate rappers, African poets","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-09-007","lineIndex":7,"speaker":"","original":"Des chanteuses engagées, engagées par personne","ipa":"/de ʃɑ̃tøzz ɑ̃ɡaʒe ɑ̃ɡaʒe paʁ pɛʁsɔn/","zh":"自诩独立的创作女歌手，实则无人问津","en":"Committed singers, hired by no one","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-09-008","lineIndex":8,"speaker":"","original":"Qui détestent le système qui d'ailleurs leur rend bien","ipa":"/ki detɛst lə sistɛm ki dajœʁ lœʁ ʁɑ̃ bjɛ̃/","zh":"她们憎恨的体系却恰是衣食父母","en":"Who hate the system which also makes them feel good","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-09-009","lineIndex":9,"speaker":"","original":"Je joue pas, du piano du violon du sax ou de l'accordéon","ipa":"/ʒə ʒu pa dy pjano dy vjolɔ̃ dy saks u də lakɔʁdeɔ̃/","zh":"我不会弹奏钢琴、小提琴、萨克斯或手风琴","en":"I don't play, the piano, the violin, the sax or the accordion","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-09-010","lineIndex":10,"speaker":"","original":"Les tournées, les promos, les clips, les billets d'avion","ipa":"/le tuʁne le pʁomo le klip le bijɛ davjɔ̃/","zh":"但巡演、宣传、MV、机票账单","en":"Tours, promos, clips, plane tickets","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-09-011","lineIndex":11,"speaker":"","original":"C'est moi qui paye la note","ipa":"/sɛ mwa ki pɛj la nɔt/","zh":"都由我来支付","en":"It's me who pays the bill","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-09-012","lineIndex":12,"speaker":"","original":"Et j'connais la chanson","ipa":"/e ʒkɔnɛ la ʃɑ̃sɔ̃/","zh":"这一切套路我早已熟悉","en":"And I know the song","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-09-013","lineIndex":13,"speaker":"","original":"La vie de producteur c'est-pas toujours la fête","ipa":"/la vi də pʁodyktœʁ sɛpa tuʒuʁ la fɛt/","zh":"制作人的生活并非总是光鲜亮丽","en":"The life of a producer is not always a party","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-09-014","lineIndex":14,"speaker":"","original":"Les soirées, les cocktails faire son show dans l'show-biz","ipa":"/le swaʁe le kɔktaj fɛʁ sɔ̃ ʃəʊ dɑ̃ ɛlʃəʊbiz/","zh":"派对、酒会、在娱乐圈秀场表演作秀","en":"Evenings, cocktails putting on a show in show biz","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-09-015","lineIndex":15,"speaker":"","original":"Pour passer chez Ruquier faut en faire des courbettes","ipa":"/puʁ pase ʃe ʁykje fot ɑ̃ fɛʁ de kuʁbɛt/","zh":"想在Ruquier的节目露面就得卑躬屈膝","en":"To get through to Ruquier you have to kowtow","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-09-016","lineIndex":16,"speaker":"","original":"A des cons qu'on déteste et leur claquer la bise","ipa":"/a de kɔ̃ kɔ̃ detɛst e lœʁ klake la biz/","zh":"对着厌恶的蠢货陪笑献吻","en":"To idiots you hate and give them a kiss","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-09-017","lineIndex":17,"speaker":"","original":"Mais c'est l'prix à payer pour être en haut des « charts »","ipa":"/mɛ sɛ ɛlpɹɪks a pɛje puʁ ɛtʁ ɑ̃ o de ʃaʁ/","zh":"但这是登顶排行榜必须付出的代价","en":"But that's the price to pay to be at the top of the \"charts\"","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-09-018","lineIndex":18,"speaker":"","original":"Pour payer ma villa et mon Aston-Martin","ipa":"/puʁ pɛje ma vila e mɔ̃n astɔ̃maʁtɛ̃/","zh":"为支付我的别墅和Aston-Martin","en":"To pay for my villa and my Aston-Martin","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-09-019","lineIndex":19,"speaker":"","original":"Je vends de l'artistique je fais dans l'efficace","ipa":"/ʒə vɑ̃ də laʁtistik ʒə fɛ dɑ̃ lefikas/","zh":"我贩卖艺术但更注重效率","en":"I sell art, I do what's efficient","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-09-020","lineIndex":20,"speaker":"","original":"C'est pas les grands principes qui remplissent ma piscine","ipa":"/sɛ pa le ɡʁɑ̃ pʁɛ̃sip ki ʁɑ̃plis ma pisin/","zh":"空谈理想可填不满我的","en":"It's not the great principles that fill my pool","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-09-021","lineIndex":21,"speaker":"","original":"Je joue pas, du piano du violon du sax ou de l'accordéon","ipa":"/ʒə ʒu pa dy pjano dy vjolɔ̃ dy saks u də lakɔʁdeɔ̃/","zh":"我不会弹奏钢琴、小提琴、萨克斯或手风琴","en":"I don't play, the piano, the violin, the sax or the accordion","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-09-022","lineIndex":22,"speaker":"","original":"Les tournées, les promos, les clips, les billets d'avion","ipa":"/le tuʁne le pʁomo le klip le bijɛ davjɔ̃/","zh":"但巡演、宣传、MV、机票账单","en":"Tours, promos, clips, plane tickets","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-09-023","lineIndex":23,"speaker":"","original":"C'est moi qui paye la note","ipa":"/sɛ mwa ki pɛj la nɔt/","zh":"都由我来支付","en":"It's me who pays the bill","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-09-024","lineIndex":24,"speaker":"","original":"Et j'connais la chanson","ipa":"/e ʒkɔnɛ la ʃɑ̃sɔ̃/","zh":"这一切套路我早已熟念于心","en":"And I know the song","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-09-025","lineIndex":25,"speaker":"","original":"Je joue pas, du piano du violon du sax ou de l'accordéon","ipa":"/ʒə ʒu pa dy pjano dy vjolɔ̃ dy saks u də lakɔʁdeɔ̃/","zh":"我不会弹奏钢琴、小提琴、萨克斯或手风琴","en":"I don't play, the piano, the violin, the sax or the accordion","note":"","sourceLineIndex":25},{"id":"cyrano-de-bergerac-09-026","lineIndex":26,"speaker":"","original":"Les tournées, les promos, les clips, les billets d'avion","ipa":"/le tuʁne le pʁomo le klip le bijɛ davjɔ̃/","zh":"但巡演、宣传、MV、机票账单","en":"Tours, promos, clips, plane tickets","note":"","sourceLineIndex":26},{"id":"cyrano-de-bergerac-09-027","lineIndex":27,"speaker":"","original":"Les calls girls, les cliniques, les psy, les opérations","ipa":"/le kɔlz ɡɜlz le klinik le psi lez opeʁasjɔ̃/","zh":"应召女郎、私人诊所、心理治疗、整形手术","en":"Call girls, clinics, psychologists, operations","note":"","sourceLineIndex":27},{"id":"cyrano-de-bergerac-09-028","lineIndex":28,"speaker":"","original":"Les mariages, les baptêmes et même les circoncisions","ipa":"/le maʁjaʒ le batɛmz e mɛm le siʁkɔ̃sizjɔ̃/","zh":"婚礼庆典、洗礼仪式甚至割礼风俗","en":"Weddings, baptisms and even circumcisions","note":"","sourceLineIndex":28},{"id":"cyrano-de-bergerac-09-029","lineIndex":29,"speaker":"","original":"C'est moi qui paye la note","ipa":"/sɛ mwa ki pɛj la nɔt/","zh":"都由我来支付","en":"It's me who pays the bill","note":"","sourceLineIndex":29},{"id":"cyrano-de-bergerac-09-030","lineIndex":30,"speaker":"","original":"Et j'connais la chanson","ipa":"/e ʒkɔnɛ la ʃɑ̃sɔ̃/","zh":"这一切套路我早已熟悉","en":"And I know the song","note":"","sourceLineIndex":30},{"id":"cyrano-de-bergerac-09-031","lineIndex":31,"speaker":"","original":"Avec moi pas d'fausses notes","ipa":"/avɛk mwa pa dfos not/","zh":"在我的掌控下绝无走音","en":"With me there are no wrong notes","note":"","sourceLineIndex":31},{"id":"cyrano-de-bergerac-09-032","lineIndex":32,"speaker":"","original":"On joue ma partition","ipa":"/ɔ̃ ʒu ma paʁtisjɔ̃/","zh":"所有人都得按我的曲谱演奏","en":"We play my part","note":"","sourceLineIndex":32}],"sourceOrder":9,"displayOrder":9},{"order":10,"id":"10-si-tu-ecris-pour-moi","title":"Si tu écris pour moi","titleZh":"若你为我写歌","lines":[{"id":"cyrano-de-bergerac-10-001","lineIndex":1,"speaker":"","original":"Ta musique et tes vers, dis-moi, ça sert à quoi?","ipa":"/ta myzik e te vɛʁ dimwa sa sɛʁ a kwa/","zh":"你的音乐和诗句，告诉我，它们有什么用？","en":"Your music and your verses—tell me, what are they for?","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-10-003","lineIndex":2,"speaker":"","original":"Si on ne les joue pas, si on ne les chante pas, tout ça n'existe pas","ipa":"/si ɔ̃ nə le ʒu pa si ɔ̃ nə le ʃɑ̃t pa tu sa nɛɡzist pa/","zh":"若无人弹奏 若无人吟唱 也就形同虚设","en":"If we don't play them, if we don't sing them, all that doesn't exist","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-10-005","lineIndex":3,"speaker":"","original":"Même s'ils sont les plus beaux tes mots restent sans voix","ipa":"/mɛm sil sɔ̃ le ply bo te mo ʁɛst sɑ̃ vwa/","zh":"哪怕是你最美的词句，没有人演唱，也依然无声","en":"Even if they are your most beautiful words, they remain voiceless","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-10-007","lineIndex":4,"speaker":"","original":"Mais ta vie changera, si tu écris pour moi","ipa":"/mɛ ta vi ʃɑ̃ʒʁa si ty ekʁi puʁ mwa/","zh":"你的人生将大有不同 若你为我写歌","en":"But your life will change, if you write for me","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-10-009","lineIndex":5,"speaker":"","original":"Je n'veux être personne c'est tout que j'écris","ipa":"/ʒə nvøz ɛtʁ pɛʁsɔn sɛ tu kə ʒekʁi/","zh":"我无心成名 我写下的一切","en":"I don't want to be anyone, that's all that I write","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-10-011","lineIndex":6,"speaker":"","original":"Qui m'apprend qui je suis, toutes les harmonies donnent un sens à ma vie","ipa":"/ki mapʁɑ̃ ki ʒə syi tut lez aʁmoni dɔnt œ̃ sɑ̃s a ma vi/","zh":"它让我明白自己是谁，每段和声都赋予我的人生意义","en":"It teaches me who I am; every harmony gives meaning to my life","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-10-013","lineIndex":7,"speaker":"","original":"Je n'veux pas le succès je veux juste être moi","ipa":"/ʒə nvø pa lə syksɛ ʒə vø ʒyst ɛtʁ mwa/","zh":"我不要成功，我只想做自己","en":"I don't want success I just want to be me","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-10-015","lineIndex":8,"speaker":"","original":"Tu seras plus que toi… si tu écris pour moi","ipa":"/ty səʁa ply kə twa si ty ekʁi puʁ mwa/","zh":"你将超越自己 若你为我写歌","en":"You will be more than you... if you write for me","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-10-017","lineIndex":9,"speaker":"","original":"Je n'vends rien ni mes notes ni mes mots","ipa":"/ʒə nvɑ̃ ʁiɛ̃ ni me not ni me mo/","zh":"我什么也不卖 不论音符或文字","en":"I don't sell anything neither my notes nor my words","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-10-019","lineIndex":10,"speaker":"","original":"J'ai pas besoin de voir mon nom plus haut","ipa":"/ʒe pa bəzwɛ̃ də vwaʁ mɔ̃ nɔ̃ ply o/","zh":"我无意看我的名字登上头条","en":"I don't need to see my name any higher","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-10-021","lineIndex":11,"speaker":"","original":"Mes deux mains c'est tout ce qu'il me faut","ipa":"/me dø mɛ̃ sɛ tu sə kil mə fo/","zh":"我的双手 就已足够","en":"My two hands are all I need","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-10-023","lineIndex":12,"speaker":"","original":"C'est le lien de mon âme au piano","ipa":"/sɛ lə ljɛ̃ də mɔ̃n am o pjano/","zh":"把我的灵魂与琴键相连","en":"It's the connection of my soul to the piano","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-10-024","lineIndex":13,"speaker":"","original":"Tu écris des chansons et moi je t'offre un nom","ipa":"/ty ekʁi de ʃɑ̃sɔ̃z e mwa ʒə tɔfʁ œ̃ nɔ̃/","zh":"你写歌曲 我赠声名","en":"You write songs and I offer you a name","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-10-026","lineIndex":14,"speaker":"","original":"J'ai tout ce qu'il te faut, écoute bien","ipa":"/ʒe tu sə kil tə fo ekut bjɛ̃/","zh":"你要的我都有 好好考虑","en":"I have everything you need, listen carefully","note":"","sourceLineIndex":26},{"id":"cyrano-de-bergerac-10-027","lineIndex":15,"speaker":"","original":"mes mots, tu monteras plus haut","ipa":"/me mo ty mɔ̃tʁa ply o/","zh":"我的话 你会登得更高","en":"my words, you will climb higher","note":"","sourceLineIndex":27},{"id":"cyrano-de-bergerac-10-028","lineIndex":16,"speaker":"","original":"Je ne suis pas le lierre, par mes notes et mes vers","ipa":"/ʒə nə syi pa lə ljɛʁ paʁ me notz e me vɛʁ/","zh":"我不攀高枝 只凭我的音符与文字","en":"I am not the ivy, by my notes and my verses","note":"","sourceLineIndex":28},{"id":"cyrano-de-bergerac-10-030","lineIndex":17,"speaker":"","original":"Jusque dans mon linceul, je monterai tout seul","ipa":"/ʒysk dɑ̃ mɔ̃ lɛ̃sœl ʒə mɔ̃tʁe tu sœl/","zh":"直到长眠黄土 我也只身独行","en":"Right into my shroud, I will ride all alone","note":"","sourceLineIndex":30},{"id":"cyrano-de-bergerac-10-032","lineIndex":18,"speaker":"","original":"Je n'vends rien","ipa":"/ʒə nvɑ̃ ʁiɛ̃/","zh":"我什么也不卖","en":"I'm not selling anything","note":"","sourceLineIndex":32},{"id":"cyrano-de-bergerac-10-033","lineIndex":19,"speaker":"","original":"Si tu écris pour moi","ipa":"/si ty ekʁi puʁ mwa/","zh":"若你为我写歌","en":"If you write for me","note":"","sourceLineIndex":33},{"id":"cyrano-de-bergerac-10-034","lineIndex":20,"speaker":"","original":"Ni mes notes ni mes mots","ipa":"/ni me not ni me mo/","zh":"不论音符或文字","en":"Neither my notes nor my words","note":"","sourceLineIndex":34},{"id":"cyrano-de-bergerac-10-035","lineIndex":21,"speaker":"","original":"Le public t'aimera","ipa":"/lə pyblik tɛmʁa/","zh":"听众会爱上你","en":"The public will love you","note":"","sourceLineIndex":35},{"id":"cyrano-de-bergerac-10-036","lineIndex":22,"speaker":"","original":"J'ai pas besoin","ipa":"/ʒe pa bəzwɛ̃/","zh":"我无意","en":"I don't need","note":"","sourceLineIndex":36},{"id":"cyrano-de-bergerac-10-037","lineIndex":23,"speaker":"","original":"On te reconnaîtra","ipa":"/ɔ̃ tə ʁəkɔnɛtʁa/","zh":"人们会认识你","en":"We will recognize you","note":"","sourceLineIndex":37},{"id":"cyrano-de-bergerac-10-038","lineIndex":24,"speaker":"","original":"De voir mon nom plus haut","ipa":"/də vwaʁ mɔ̃ nɔ̃ ply o/","zh":"看我的名字登上头条","en":"To see my name higher","note":"","sourceLineIndex":38},{"id":"cyrano-de-bergerac-10-039","lineIndex":25,"speaker":"","original":"Si tu écris pour moi","ipa":"/si ty ekʁi puʁ mwa/","zh":"若你为我写歌","en":"If you write for me","note":"","sourceLineIndex":39},{"id":"cyrano-de-bergerac-10-040","lineIndex":26,"speaker":"","original":"Laisse moi…","ipa":"/lɛs mwa/","zh":"放过我","en":"Let me…","note":"","sourceLineIndex":40},{"id":"cyrano-de-bergerac-10-041","lineIndex":27,"speaker":"","original":"J'ai tout ce qu'il me faut","ipa":"/ʒe tu sə kil mə fo/","zh":"我一无所缺","en":"I have everything I need","note":"","sourceLineIndex":41},{"id":"cyrano-de-bergerac-10-042","lineIndex":28,"speaker":"","original":"Mais l'amour…","ipa":"/mɛ lamuʁ/","zh":"那爱情","en":"But love…","note":"","sourceLineIndex":42},{"id":"cyrano-de-bergerac-10-043","lineIndex":29,"speaker":"","original":"Mais l'amour…","ipa":"/mɛ lamuʁ/","zh":"那爱情","en":"But love…","note":"","sourceLineIndex":43},{"id":"cyrano-de-bergerac-10-044","lineIndex":30,"speaker":"","original":"Il vit dans mon piano…","ipa":"/il vi dɑ̃ mɔ̃ pjano/","zh":"就在我的钢琴中","en":"It lives in my piano…","note":"","sourceLineIndex":44},{"id":"cyrano-de-bergerac-10-045","lineIndex":31,"speaker":"","original":"Tu n'es rien","ipa":"/ty nɛ ʁjɛ̃/","zh":"你一文不名","en":"You are nothing","note":"","sourceLineIndex":45},{"id":"cyrano-de-bergerac-10-046","lineIndex":32,"speaker":"","original":"C'est tout ce que j'écris","ipa":"/sɛ tu sə kə ʒekʁi/","zh":"我写下的一切","en":"It's everything I write","note":"","sourceLineIndex":46},{"id":"cyrano-de-bergerac-10-047","lineIndex":33,"speaker":"","original":"Que des notes et des mots","ipa":"/kə de notz e de mo/","zh":"只有音符与文字","en":"Only notes and words","note":"","sourceLineIndex":47},{"id":"cyrano-de-bergerac-10-048","lineIndex":34,"speaker":"","original":"Qui fait ce que je suis","ipa":"/ki fɛ sə kə ʒə sɥi/","zh":"造就了今日的我","en":"Who makes what I am","note":"","sourceLineIndex":48},{"id":"cyrano-de-bergerac-10-049","lineIndex":35,"speaker":"","original":"Et demain","ipa":"/e dəmɛ̃/","zh":"到明日","en":"And tomorrow","note":"","sourceLineIndex":49},{"id":"cyrano-de-bergerac-10-050","lineIndex":36,"speaker":"","original":"J'ai tout ce qu'il me faut","ipa":"/ʒe tu sə kil mə fo/","zh":"我一无所缺","en":"I have everything I need","note":"","sourceLineIndex":50},{"id":"cyrano-de-bergerac-10-051","lineIndex":37,"speaker":"","original":"Tu tomberas de haut","ipa":"/ty tɔ̃bʁa də o/","zh":"你将跌下云端","en":"You will fall from a height","note":"","sourceLineIndex":51},{"id":"cyrano-de-bergerac-10-052","lineIndex":38,"speaker":"","original":"J'en payerai le prix","ipa":"/ʒɑ̃ pɛjʁe lə pʁi/","zh":"我心甘情愿","en":"I will pay the price","note":"","sourceLineIndex":52},{"id":"cyrano-de-bergerac-10-053","lineIndex":39,"speaker":"","original":"Je t'en prie","ipa":"/ʒə tɑ̃ pʁi/","zh":"我恳求你","en":"Please","note":"","sourceLineIndex":53},{"id":"cyrano-de-bergerac-10-054","lineIndex":40,"speaker":"","original":"J'ai tout ce qu'il te faut","ipa":"/ʒe tu sə kil tə fo/","zh":"我一无所缺","en":"I have everything you need","note":"","sourceLineIndex":54},{"id":"cyrano-de-bergerac-10-055","lineIndex":41,"speaker":"","original":"Même l'amour…","ipa":"/mɛm lamuʁ/","zh":"就连爱情","en":"Even love…","note":"","sourceLineIndex":55},{"id":"cyrano-de-bergerac-10-056","lineIndex":42,"speaker":"","original":"Même l'amour…","ipa":"/mɛm lamuʁ/","zh":"就连爱情","en":"Even love…","note":"","sourceLineIndex":56},{"id":"cyrano-de-bergerac-10-057","lineIndex":43,"speaker":"","original":"Vivra dans mon piano…","ipa":"/vivʁa dɑ̃ mɔ̃ pjano/","zh":"也将在我的钢琴中","en":"Will live in my piano…","note":"","sourceLineIndex":57},{"id":"cyrano-de-bergerac-10-058","lineIndex":44,"speaker":"","original":"Mon amour vivra dans mes chansons","ipa":"/mɔ̃n amuʁ vivʁa dɑ̃ me ʃɑ̃sɔ̃/","zh":"我的爱将在我的歌中","en":"My love will live in my songs","note":"","sourceLineIndex":58},{"id":"cyrano-de-bergerac-10-059","lineIndex":45,"speaker":"","original":"Pour Roxane j'effacerai mon nom…","ipa":"/puʁ ʁoksan ʒefasʁe mɔ̃ nɔ̃/","zh":"为了罗克珊 我将抹去我的姓名","en":"For Roxane I will erase my name…","note":"","sourceLineIndex":59}],"sourceOrder":10,"displayOrder":10},{"order":11,"id":"11-mon-evidence","title":"Mon évidence","titleZh":"命中注定","lines":[{"id":"cyrano-de-bergerac-11-001","lineIndex":1,"speaker":"","original":"Le hasard est fragile","ipa":"/lə azaʁ ɛ fʁaʒil/","zh":"偶然何其脆弱","en":"Chance is fragile","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-11-002","lineIndex":2,"speaker":"","original":"Et l'océan si grand","ipa":"/e loseɑ̃ si ɡʁɑ̃/","zh":"海洋浩瀚辽阔","en":"And the ocean so big","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-11-003","lineIndex":3,"speaker":"","original":"Il y a si peu d'îles","ipa":"/il i a si pø dil/","zh":"岛屿寥寥无多","en":"There are so few islands","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-11-004","lineIndex":4,"speaker":"","original":"Et pour te trouver j'ai mis, tellement de temps","ipa":"/e puʁ tə tʁuve ʒe mi tɛlmɑ̃ də tɑ̃/","zh":"为了找到你 花了多少时间","en":"And to find you I took so much time","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-11-005","lineIndex":5,"speaker":"","original":"J'ai fait le tour de la terre","ipa":"/ʒe fɛ lə tuʁ də la tɛʁ/","zh":"把整个世界走遍","en":"I went around the earth","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-11-006","lineIndex":6,"speaker":"","original":"Tu m'attendais ici","ipa":"/ty matɑ̃dɛz isi/","zh":"而你就在这等待","en":"You were waiting for me here","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-11-007","lineIndex":7,"speaker":"","original":"Mon paradis, mon paradis…","ipa":"/mɔ̃ paʁadi mɔ̃ paʁadi/","zh":"我的天堂 我的天堂","en":"My paradise, my paradise...","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-11-008","lineIndex":8,"speaker":"","original":"Je ne suis né que pour vous","ipa":"/ʒə nə sɥi ne kə puʁ vu/","zh":"我只为你而生","en":"I was only born for you","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-11-009","lineIndex":9,"speaker":"","original":"Vous étiez mon rendez-vous, mon ciel immense, mon évidence","ipa":"/vuz etje mɔ̃ ʁɑ̃devu mɔ̃ sjɛl imɑ̃s mɔ̃n evidɑ̃s/","zh":"你是我的今世相逢 我的海阔天空 我的命中注定","en":"You were my date, my immense sky, my evidence","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-11-010","lineIndex":10,"speaker":"","original":"Je ne vivais que pour vous, mes voyages allaient vers vous","ipa":"/ʒə nə vivɛ kə puʁ vu me vwajaʒz alɛ vɛʁ vu/","zh":"我只为你而活 我的旅程都通向你","en":"I only lived for you, my travels went towards you","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-11-011","lineIndex":11,"speaker":"","original":"Mon espérance, mon autre chance","ipa":"/mɔ̃n ɛspeʁɑ̃s mɔ̃n otʁ ʃɑ̃s/","zh":"我的期许 我的另一种可能","en":"My hope, my other chance","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-11-012","lineIndex":12,"speaker":"","original":"C'est vous …","ipa":"/sɛ vu/","zh":"都是你","en":"It’s you…","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-11-013","lineIndex":13,"speaker":"","original":"Le désir est fragile","ipa":"/lə deziʁ ɛ fʁaʒil/","zh":"欲望何其脆弱","en":"Desire is fragile","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-11-014","lineIndex":14,"speaker":"","original":"Et mon amour si grand","ipa":"/e mɔ̃n amuʁ si ɡʁɑ̃/","zh":"爱却浩瀚辽阔","en":"And my love so great","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-11-015","lineIndex":15,"speaker":"","original":"Les mots sont inutiles","ipa":"/le mo sɔ̃t inytil/","zh":"词句用处无多","en":"Words are useless","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-11-016","lineIndex":16,"speaker":"","original":"Et pour s'aimer il reste, si peu de temps","ipa":"/e puʁ sɛme il ʁɛst si pø də tɑ̃/","zh":"相爱的时光 也所剩无几","en":"And there is so little time left to love each other","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-11-017","lineIndex":17,"speaker":"","original":"J'ai fait le tour de l'enfer","ipa":"/ʒe fɛ lə tuʁ də lɑ̃fɛʁ/","zh":"把整个地狱走遍","en":"I have been around hell","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-11-018","lineIndex":18,"speaker":"","original":"Tu m'attendais ici","ipa":"/ty matɑ̃dɛz isi/","zh":"而你就在这等待","en":"You were waiting for me here","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-11-019","lineIndex":19,"speaker":"","original":"Mon paradis, mon paradis…","ipa":"/mɔ̃ paʁadi mɔ̃ paʁadi/","zh":"我的天堂 我的天堂","en":"My paradise, my paradise...","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-11-020","lineIndex":20,"speaker":"","original":"Je ne suis né que pour vous","ipa":"/ʒə nə sɥi ne kə puʁ vu/","zh":"我只为你而生","en":"I was only born for you","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-11-021","lineIndex":21,"speaker":"","original":"Vous étiez mon rendez-vous, mon ciel immense, mon évidence","ipa":"/vuz etje mɔ̃ ʁɑ̃devu mɔ̃ sjɛl imɑ̃s mɔ̃n evidɑ̃s/","zh":"你是我的今世相逢 我的海阔天空 我的命中注定","en":"You were my date, my immense sky, my evidence","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-11-022","lineIndex":22,"speaker":"","original":"Je ne vivais que pour vous, mes voyages allaient vers vous","ipa":"/ʒə nə vivɛ kə puʁ vu me vwajaʒz alɛ vɛʁ vu/","zh":"我只为你而活 我的旅程都通向你","en":"I only lived for you, my travels went towards you","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-11-023","lineIndex":23,"speaker":"","original":"Mon espérance, mon autre chance","ipa":"/mɔ̃n ɛspeʁɑ̃s mɔ̃n otʁ ʃɑ̃s/","zh":"我的期许 我的另一种可能","en":"My hope, my other chance","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-11-024","lineIndex":24,"speaker":"","original":"C'était vous …","ipa":"/setɛ vu/","zh":"就是你","en":"It was you...","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-11-025","lineIndex":25,"speaker":"","original":"Je n'ai besoin que de vous","ipa":"/ʒə ne bəzwɛ̃ kə də vu/","zh":"我需要的唯有你","en":"I only need you","note":"","sourceLineIndex":25},{"id":"cyrano-de-bergerac-11-026","lineIndex":26,"speaker":"","original":"Mon cœur ne bat que pour vous","ipa":"/mɔ̃ kœʁ nə ba kə puʁ vu/","zh":"我的心只为你跳动","en":"My heart beats only for you","note":"","sourceLineIndex":26},{"id":"cyrano-de-bergerac-11-027","lineIndex":27,"speaker":"","original":"Mon ciel immense, mon évidence","ipa":"/mɔ̃ sjɛl imɑ̃s mɔ̃n evidɑ̃s/","zh":"我的海阔天空 我的命中注定","en":"My immense sky, my self-evidence","note":"","sourceLineIndex":27},{"id":"cyrano-de-bergerac-11-028","lineIndex":28,"speaker":"","original":"Mon autre chance","ipa":"/mɔ̃n otʁ ʃɑ̃s/","zh":"我的另一种可能","en":"My other chance","note":"","sourceLineIndex":28},{"id":"cyrano-de-bergerac-11-029","lineIndex":29,"speaker":"","original":"Tout recommence… Avec vous","ipa":"/tu ʁəkɔmɑ̃s avɛk vu/","zh":"一切颠覆重生 为你","en":"Everything starts again... With you","note":"","sourceLineIndex":29}],"sourceOrder":11,"displayOrder":11},{"order":12,"id":"12-c-est-pas-d-ma-faute","title":"C'est pas d'ma faute","titleZh":"错不在我","lines":[{"id":"cyrano-de-bergerac-12-001","lineIndex":1,"speaker":"","original":"Merci pour ce face à face","ipa":"/mɛʁsi puʁ sə fas a fas/","zh":"感谢这次面对面","en":"Thank you for this face to face","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-12-002","lineIndex":2,"speaker":"","original":"J'suis pas poète mais j'ai d'l'audace","ipa":"/ʒsɥi pa pɔɛt mɛ ʒe dəlɔdeɪs/","zh":"我不是诗人 但我却有胆识","en":"I'm not a poet but I have of audacity","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-12-003","lineIndex":3,"speaker":"","original":"Les mots d'amour me glacent","ipa":"/le mo damuʁ mə ɡlas/","zh":"情话梗在我的喉中","en":"Words of love freeze me","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-12-004","lineIndex":4,"speaker":"","original":"Excuse par avance mes couacs","ipa":"/ɛkskyz paʁ avɑ̃s me kwak/","zh":"先为我的冒失抱歉","en":"Excuse in advance my hiccups","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-12-005","lineIndex":5,"speaker":"","original":"Mais j't'avouerai que j'ai le trac","ipa":"/mɛ dʒeɪtɐvaʊəɹaɪ kə ʒe lə tʁak/","zh":"我承认我有点怯场","en":"But I will admit to you that I have stage fright","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-12-006","lineIndex":6,"speaker":"","original":"J'ai le cœur qui s'détraque","ipa":"/ʒe lə kœʁ ki sdetʁak/","zh":"连心跳都错了拍","en":"My heart goes haywire","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-12-007","lineIndex":7,"speaker":"","original":"Quand je suis en face","ipa":"/kɑ̃ ʒə sɥiz ɑ̃ fas/","zh":"当我站在你面前","en":"When I'm in front of you","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-12-008","lineIndex":8,"speaker":"","original":"De toi je suis en vrac","ipa":"/də twa ʒə sɥiz ɑ̃ vʁak/","zh":"我简直手足无措","en":"From you I'm loose","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-12-009","lineIndex":9,"speaker":"","original":"J'suis plus efficace","ipa":"/ʒsɥi plyz efikas/","zh":"完全不在状态","en":"I'm more efficient","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-12-010","lineIndex":10,"speaker":"","original":"C''est pas d'ma faute","ipa":"/se ɛ pa dma fot/","zh":"错不在我","en":"It's not my fault","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-12-011","lineIndex":11,"speaker":"","original":"J'ai jamais su écrire toutes ces choses là","ipa":"/ʒe ʒamɛ sy ekʁiʁ tut se ʃoz la/","zh":"我一向不擅长遣词造句","en":"I never knew how to write all these things","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-12-012","lineIndex":12,"speaker":"","original":"C''est pas d'ma faute","ipa":"/se ɛ pa dma fot/","zh":"错不在我","en":"It's not my fault","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-12-013","lineIndex":13,"speaker":"","original":"Mais je sais sans les dire","ipa":"/mɛ ʒə sɛ sɑ̃ le diʁ/","zh":"但就算不说出口","en":"But I know without saying them","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-12-014","lineIndex":14,"speaker":"","original":"Que tu comprendras","ipa":"/kə ty kɔ̃pʁɑ̃dʁa/","zh":"我也知道你会懂","en":"That you will understand","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-12-015","lineIndex":15,"speaker":"","original":"Il n'y a qu'un diagnostic","ipa":"/il ni a kœ̃ djaɡnɔstik/","zh":"诊断结果只有一个","en":"There is only one diagnosis","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-12-016","lineIndex":16,"speaker":"","original":"Si j'ai pas la sémantique","ipa":"/si ʒe pa la semɑ̃tik/","zh":"我纯属是文盲一个","en":"If I don't have the semantics","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-12-017","lineIndex":17,"speaker":"","original":"Je connais la musique","ipa":"/ʒə kɔnɛ la myzik/","zh":"可我懂音乐会唱歌","en":"I know the music","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-12-018","lineIndex":18,"speaker":"","original":"J'suis pas fort en thème","ipa":"/ʒsɥi pa fɔʁ ɑ̃ tɛm/","zh":"我实在是笨嘴拙舌","en":"I'm not good at themes","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-12-019","lineIndex":19,"speaker":"","original":"J'ai trouvé la rythmique","ipa":"/ʒe tʁuve la ɹɪθmik/","zh":"但我找到了节奏","en":"I found the rhythm","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-12-020","lineIndex":20,"speaker":"","original":"Pour te dire je t'aime","ipa":"/puʁ tə diʁ ʒə tɛm/","zh":"来告诉你我爱你","en":"For tell you I love you","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-12-021","lineIndex":21,"speaker":"","original":"C''est pas d'ma faute","ipa":"/se ɛ pa dma fot/","zh":"错不在我","en":"It's not my fault","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-12-022","lineIndex":22,"speaker":"","original":"J'ai jamais su écrire toutes ces choses là","ipa":"/ʒe ʒamɛ sy ekʁiʁ tut se ʃoz la/","zh":"我一向不擅长遣词造句","en":"I never knew how to write all these things","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-12-023","lineIndex":23,"speaker":"","original":"C''est pas d'ma faute","ipa":"/se ɛ pa dma fot/","zh":"错不在我","en":"It's not my fault","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-12-024","lineIndex":24,"speaker":"","original":"Mais je sais sans les dire que tu comprendras","ipa":"/mɛ ʒə sɛ sɑ̃ le diʁ kə ty kɔ̃pʁɑ̃dʁa/","zh":"但就算不说出口 我也知道你会懂","en":"But I know without saying them that you will understand","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-12-025","lineIndex":25,"speaker":"","original":"Pardon si j'ai pas l'talent","ipa":"/paʁdɔ̃ si ʒe pa ltalɑ̃/","zh":"抱歉我没那个天分","en":"Sorry if I don't have the talent","note":"","sourceLineIndex":25},{"id":"cyrano-de-bergerac-12-026","lineIndex":26,"speaker":"","original":"Pour susurrer des serments","ipa":"/puʁ syzyʁe de sɛʁmɑ̃/","zh":"低诉什么海誓山盟","en":"To whisper oaths","note":"","sourceLineIndex":26},{"id":"cyrano-de-bergerac-12-027","lineIndex":27,"speaker":"","original":"L'amour c'est mieux que les mots","ipa":"/lamuʁ sɛ mjø kə le mo/","zh":"爱比言语更直接","en":"Love is better than words","note":"","sourceLineIndex":27},{"id":"cyrano-de-bergerac-12-028","lineIndex":28,"speaker":"","original":"Pas de quiproquo","ipa":"/pa də kipʁoko/","zh":"不要误会","en":"No misunderstandings","note":"","sourceLineIndex":28},{"id":"cyrano-de-bergerac-12-029","lineIndex":29,"speaker":"","original":"Alors…","ipa":"/alɔʁ/","zh":"那么","en":"So...","note":"","sourceLineIndex":29},{"id":"cyrano-de-bergerac-12-030","lineIndex":30,"speaker":"","original":"J'en dirai pas trop …","ipa":"/ʒɑ̃ diʁe pa tʁo/","zh":"我就不多说了","en":"I won't say too much...","note":"","sourceLineIndex":30},{"id":"cyrano-de-bergerac-12-031","lineIndex":31,"speaker":"","original":"A qui la faute?","ipa":"/a ki la fot/","zh":"该怪谁呢","en":"Who is to blame?","note":"","sourceLineIndex":31},{"id":"cyrano-de-bergerac-12-032","lineIndex":32,"speaker":"","original":"C'est pas d'ma faute","ipa":"/sɛ pa dma fot/","zh":"错不在我","en":"It's not my fault","note":"","sourceLineIndex":32},{"id":"cyrano-de-bergerac-12-033","lineIndex":33,"speaker":"","original":"J'ai jamais su écrire toutes ces choses là","ipa":"/ʒe ʒamɛ sy ekʁiʁ tut se ʃoz la/","zh":"我一向不擅长遣词造句","en":"I never knew how to write all these things","note":"","sourceLineIndex":33},{"id":"cyrano-de-bergerac-12-034","lineIndex":34,"speaker":"","original":"C''est pas d'ma faute","ipa":"/se ɛ pa dma fot/","zh":"错不在我","en":"It's not my fault","note":"","sourceLineIndex":34},{"id":"cyrano-de-bergerac-12-035","lineIndex":35,"speaker":"","original":"Mais je sais sans les dire que tu comprendras","ipa":"/mɛ ʒə sɛ sɑ̃ le diʁ kə ty kɔ̃pʁɑ̃dʁa/","zh":"但就算不说出口 我也知道你会懂","en":"But I know without saying them that you will understand","note":"","sourceLineIndex":35}],"sourceOrder":12,"displayOrder":12},{"order":13,"id":"13-le-serment","title":"Le serment","titleZh":"誓言","lines":[{"id":"cyrano-de-bergerac-13-001","lineIndex":1,"speaker":"","original":"On hésite, on voudrait, on recule, on attend","ipa":"/ɔ̃n ezit ɔ̃ vudʁɛ ɔ̃ ʁəkyl ɔ̃n atɑ̃/","zh":"犹豫着 渴望着 退缩着 等待着","en":"We hesitate, we wish, we step back, we wait","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-13-002","lineIndex":2,"speaker":"","original":"On reporte, on remet à plus tard tout le temps","ipa":"/ɔ̃ ʁəpɔʁt ɔ̃ ʁəmɛt a ply taʁ tultɑ̃/","zh":"逃避着 一味一拖再拖","en":"We postpone, we procrastinate all the time","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-13-003","lineIndex":3,"speaker":"","original":"On réfléchit encore, et encore tant et tant","ipa":"/ɔ̃ ʁefleʃit ɑ̃kɔʁ e ɑ̃kɔʁ tɑ̃t e tɑ̃/","zh":"思忖着 无数次重复","en":"We think again, and again and again","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-13-004","lineIndex":4,"speaker":"","original":"Les pensées sont les ombres de nos sentiments","ipa":"/le pɑ̃se sɔ̃ lez ɔ̃bʁ də no sɑ̃timɑ̃/","zh":"思想是情感的投射","en":"Thoughts are the shadows of our feelings","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-13-005","lineIndex":5,"speaker":"","original":"Dis-toi qu'au bout du compte il reste le présent","ipa":"/ditwa ko bu dy kɔ̃t il ʁɛst lə pʁezɑ̃/","zh":"告诉你 到头来只剩当下","en":"Tell yourself that in the end there remains the present","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-13-006","lineIndex":6,"speaker":"","original":"L'éternel se décline ici et maintenant","ipa":"/letɛʁnɛl sə deklin isi e mɛ̃tnɑ̃/","zh":"永恒就在此时此刻","en":"The eternal is expressed here and now","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-13-007","lineIndex":7,"speaker":"","original":"Allez, viens, mets ta main dans la mienne","ipa":"/ale vjɛ̃ mɛ ta mɛ̃ dɑ̃ la mjɛn/","zh":"来吧 把你的手放进我手心","en":"Come on, put your hand in mine","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-13-008","lineIndex":8,"speaker":"","original":"Et dis-toi bien que même","ipa":"/e ditwa bjɛ̃ kə mɛm/","zh":"告诉自己 无论如何","en":"And tell yourself that even","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-13-009","lineIndex":9,"speaker":"","original":"Même s'il n'existe pas, Dieu sait combien je t'aime","ipa":"/mɛm sil nɛɡzist pa djø sɛ kɔ̃bjɛ̃ ʒə tɛm/","zh":"上帝知道我多爱你 哪怕他不曾存在","en":"Even if it does not exist, God knows how much I love you","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-13-010","lineIndex":10,"speaker":"","original":"Mets ta main dans la mienne","ipa":"/mɛ ta mɛ̃ dɑ̃ la mjɛn/","zh":"把你的手放进我手心","en":"Put your hand in mine","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-13-011","lineIndex":11,"speaker":"","original":"Même s'il n'existe pas, Dieu sait combien je t'aime","ipa":"/mɛm sil nɛɡzist pa djø sɛ kɔ̃bjɛ̃ ʒə tɛm/","zh":"上帝知道我多爱你 哪怕他不曾存在","en":"Even if it does not exist, God knows how much I love you","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-13-012","lineIndex":12,"speaker":"","original":"Si tu m'aimes vraiment Il y'a si longtemps","ipa":"/si ty mɛm vʁɛmɑ̃ il ja si lɔ̃tɑ̃/","zh":"你是否真的爱我 -这么久以来","en":"If you really love me So long ago","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-13-013","lineIndex":13,"speaker":"","original":"Comme je t'aime, vraiment Que je t'attends","ipa":"/kɔm ʒə tɛm vʁɛmɑ̃ kə ʒə tatɑ̃/","zh":"如我爱你一般真诚 -我一直在等你","en":"How I love you, really That I'm waiting for you","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-13-014","lineIndex":14,"speaker":"","original":"Si tu as toi aussi Dans le corps ce volcan","ipa":"/si ty a twa osi dɑ̃ lə kɔʁ sə vɔlkɑ̃/","zh":"你是否也有 -身体里的火山","en":"If you too have This volcano in your body","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-13-015","lineIndex":15,"speaker":"","original":"Cette lave qui brûle Mon cœur incandescent","ipa":"/sɛt lav ki bʁyl mɔ̃ kœʁ ɛ̃kɑ̃dɛsɑ̃/","zh":"那滚烫的熔岩 -让我的心炽热","en":"This lava that burns My incandescent heart","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-13-016","lineIndex":16,"speaker":"","original":"Si tu veux toi aussi Ce dont je rêve tant","ipa":"/si ty vø twa osi sə dɔ̃ ʒə ʁɛv tɑ̃/","zh":"你是否也渴望 -我梦寐以求的","en":"If you want too What I dream of so much","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-13-017","lineIndex":17,"speaker":"","original":"Mets ta main que j'attends Dans ma main qui se tend","ipa":"/mɛ ta mɛ̃ kə ʒatɑ̃ dɑ̃ ma mɛ̃ ki sə tɑ̃/","zh":"我等你伸出手 -在伸出的手中","en":"Put your hand that I am waiting for In my hand that is tense","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-13-018","lineIndex":18,"speaker":"","original":"Ton cœur contre mon cœur Contre moi doucement","ipa":"/tɔ̃ kœʁ kɔ̃tʁ mɔ̃ kœʁ kɔ̃tʁ mwa dusmɑ̃/","zh":"你的心贴着我的心 -轻轻贴近我","en":"Your heart against my heart Against me gently","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-13-019","lineIndex":19,"speaker":"","original":"Allez, viens, mets ta main dans la mienne","ipa":"/ale vjɛ̃ mɛ ta mɛ̃ dɑ̃ la mjɛn/","zh":"来吧 把你的手放进我手心","en":"Come on, put your hand in mine","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-13-020","lineIndex":20,"speaker":"","original":"Et dis-toi bien que même","ipa":"/e ditwa bjɛ̃ kə mɛm/","zh":"告诉自己 无论如何","en":"And tell yourself that even","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-13-021","lineIndex":21,"speaker":"","original":"Même s'il n'existe pas Dieu sait combien je t'aime","ipa":"/mɛm sil nɛɡzist pa djø sɛ kɔ̃bjɛ̃ ʒə tɛm/","zh":"上帝知道我多爱你 哪怕他不曾存在","en":"Even if it does not exist God knows how much I love you","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-13-022","lineIndex":22,"speaker":"","original":"Mets ta main dans la mienne","ipa":"/mɛ ta mɛ̃ dɑ̃ la mjɛn/","zh":"把你的手放进我手心","en":"Put your hand in mine","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-13-023","lineIndex":23,"speaker":"","original":"Même s'il n'existe pas, Dieu sait combien je t'aime","ipa":"/mɛm sil nɛɡzist pa djø sɛ kɔ̃bjɛ̃ ʒə tɛm/","zh":"上帝知道我有多爱你 哪怕他不曾存在","en":"Even if it does not exist, God knows how much I love you","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-13-024","lineIndex":24,"speaker":"","original":"Les pensées sont les ombres de nos sentiments","ipa":"/le pɑ̃se sɔ̃ lez ɔ̃bʁ də no sɑ̃timɑ̃/","zh":"思想是情感的投射","en":"Thoughts are the shadows of our feelings","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-13-025","lineIndex":25,"speaker":"","original":"L'éternel se décline ici et maintenant ici et maintenant","ipa":"/letɛʁnɛl sə deklin isi e mɛ̃tnɑ̃ isi e mɛ̃tnɑ̃/","zh":"永恒就在此时此刻","en":"The eternal is expressed here and now here and now","note":"","sourceLineIndex":25},{"id":"cyrano-de-bergerac-13-026","lineIndex":26,"speaker":"","original":"Ton cœur contre mon cœur vient poser doucement…","ipa":"/tɔ̃ kœʁ kɔ̃tʁ mɔ̃ kœʁ vjɛ̃ poze dusmɑ̃/","zh":"你的心贴着我的心 来吧轻轻靠近","en":"Your heart against my heart comes to gently place…","note":"","sourceLineIndex":26},{"id":"cyrano-de-bergerac-13-027","lineIndex":27,"speaker":"","original":"…Tes lèvres sur ses lèvres en guise de serment","ipa":"/te lɛvʁ syʁ se lɛvʁz ɑ̃ ɡiz də sɛʁmɑ̃/","zh":"你的唇落上他的唇 作为爱的誓言","en":"…Your lips on his lips as an oath","note":"","sourceLineIndex":27}],"sourceOrder":13,"displayOrder":13},{"order":14,"id":"14-c-est-ma-tournee","title":"C'est ma tournée","titleZh":"我的巡演","lines":[{"id":"cyrano-de-bergerac-14-001","lineIndex":1,"speaker":"","original":"J'ai une surprise, écoute mon grand","ipa":"/ʒe yn syʁpʁiz ekut mɔ̃ ɡʁɑ̃/","zh":"我有个惊喜要告诉你，听好了伙计","en":"I have a surprise, listen big boy","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-14-002","lineIndex":2,"speaker":"","original":"On va savoir maint'nant","ipa":"/ɔ̃ va savwaʁ meɪntnənt/","zh":"现在就要见分晓","en":"We're going to know now","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-14-003","lineIndex":3,"speaker":"","original":"On va savoir, savoir vraiment","ipa":"/ɔ̃ va savwaʁ savwaʁ vʁɛmɑ̃/","zh":"马上就知道，真真正正地知道","en":"We're going to know, really know","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-14-004","lineIndex":4,"speaker":"","original":"Si t'es une star ou un coup d'vent","ipa":"/si tɛz yn staʁ u œ̃ ku dvɑ̃/","zh":"你到底是明星，还是昙花一现","en":"If you're a star or a hot shot","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-14-005","lineIndex":5,"speaker":"","original":"Face au public c'est là qu'ça s'passe","ipa":"/fas o pyblik sɛ la kwsa spas/","zh":"站在观众面前才是真正的考验","en":"In front of the public that's where it happens","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-14-006","lineIndex":6,"speaker":"","original":"Ça clique ou bien ça casse","ipa":"/sa klik u bjɛ̃ sa kas/","zh":"要么成功，要么破碎","en":"It either clicks it breaks","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-14-007","lineIndex":7,"speaker":"","original":"On chante plus dans sa salle de bain","ipa":"/ɔ̃ ʃɑ̃t ply dɑ̃ sa sal də bɛ̃/","zh":"别再在浴室里唱歌了","en":"We sing no more in the bathroom","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-14-008","lineIndex":8,"speaker":"","original":"Changement d'décor… on part demain","ipa":"/tʃaŋmənt ddekɔʁ ɔ̃ paʁ dəmɛ̃/","zh":"场景换了…我们明天就出发","en":"Change of scenery… we leave tomorrow","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-14-009","lineIndex":9,"speaker":"","original":"Des stades de foot, des salles des fêtes","ipa":"/de stad də fʊt de sal de fɛt/","zh":"足球场，宴会厅","en":"Football stadiums, village halls","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-14-010","lineIndex":10,"speaker":"","original":"Des filles en pleurs des mères défaites","ipa":"/de fijz ɑ̃ plœʁ de mɛʁ defɛt/","zh":"哭泣的姑娘，心碎的母亲","en":"Crying daughters, defeated mothers","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-14-011","lineIndex":11,"speaker":"","original":"Tu veux d'l'amour j'vais t'en donner","ipa":"/ty vø dəlamə ʒvɛ tɑ̃ dɔne/","zh":"你不是想要爱吗？我会给你爱","en":"You want love, I will give it to you","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-14-012","lineIndex":12,"speaker":"","original":"Fais tes valises c'est ta tournée","ipa":"/fɛ te valiz sɛ ta tuʁne/","zh":"收拾行李吧，这是你的巡演","en":"Pack your bags, it's your tour","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-14-013","lineIndex":13,"speaker":"","original":"Avec des bravos pleins la tête","ipa":"/avɛk de bʁavo plɛ̃ la tɛt/","zh":"满脑子的喝彩声","en":"With a head full of bravos","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-14-014","lineIndex":14,"speaker":"","original":"T'oublieras vite tes amourettes","ipa":"/tubliʁa vit tez amuʁɛt/","zh":"你会很快忘记那些短暂恋情","en":"You'll quickly forget your crushes","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-14-015","lineIndex":15,"speaker":"","original":"Et pas la peine de m' remercier","ipa":"/e pa la pɛn də ɛm ʁəmɛʁsje/","zh":"也不用感谢我","en":"And no need to thank me","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-14-016","lineIndex":16,"speaker":"","original":"C'est pas la peine… C'est ma tournée","ipa":"/sɛ pa la pɛn sɛ ma tuʁne/","zh":"没必要…这是我的巡演","en":"It's not worth it... It's my tour","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-14-017","lineIndex":17,"speaker":"","original":"T'as l'air surpris fais pas cette tête","ipa":"/ta lɛʁ syʁpʁi fɛ pa sɛt tɛt/","zh":"你看起来很惊讶，别摆出那副表情","en":"You look surprised don't make that face","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-14-018","lineIndex":18,"speaker":"","original":"Tu verras ce s'ra chouette","ipa":"/ty vɛʁa sə sʁa ʃwɛt/","zh":"你会看到这会很棒的","en":"You'll see it'll be nice","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-14-019","lineIndex":19,"speaker":"","original":"A la fin tu m'remercieras","ipa":"/a la fɛ̃ ty mʁəmɛʁsiʁa/","zh":"最后你会感谢我的","en":"At the end you'll thank me","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-14-020","lineIndex":20,"speaker":"","original":"Puis toute façon t'es sous contrat","ipa":"/pɥi tut fasɔ̃ tɛ su kɔ̃tʁa/","zh":"反正你已经签了合同","en":"Then anyway you're under contract","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-14-021","lineIndex":21,"speaker":"","original":"Prends ta guitare ta brosse à dent","ipa":"/pʁɑ̃ ta ɡitaʁ ta bʁɔs a dɑ̃/","zh":"带上你的吉他和牙刷","en":"Take your guitar your toothbrush","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-14-022","lineIndex":22,"speaker":"","original":"Tout ton fan club t'attend","ipa":"/tu tɔ̃ fan klœb tatɑ̃/","zh":"你的所有粉丝都在等着","en":"Your whole fan club is waiting for you","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-14-023","lineIndex":23,"speaker":"","original":"Non t'as pas l'temps d'faire tes adieux… ça…","ipa":"/nɔ̃ ta pa ltɑ̃ dfɛʁ tez adjø sa/","zh":"不，你没时间告别了…","en":"No, you don't have time to say goodbye... that...","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-14-024","lineIndex":24,"speaker":"","original":"Ce s'ra sur scène quand tu s'ras vieux","ipa":"/sə sʁa syʁ sɛn kɑ̃ ty sʁa vjø/","zh":"等你老了，就在舞台上告别吧","en":"It'll be on stage when you're old","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-14-025","lineIndex":25,"speaker":"","original":"Des stades de foot, des salles des fêtes","ipa":"/de stad də fʊt de sal de fɛt/","zh":"足球场，宴会厅","en":"Football stadiums, village halls","note":"","sourceLineIndex":25},{"id":"cyrano-de-bergerac-14-026","lineIndex":26,"speaker":"","original":"Des filles en pleurs des mères défaites","ipa":"/de fijz ɑ̃ plœʁ de mɛʁ defɛt/","zh":"哭泣的姑娘，心碎的母亲","en":"Crying daughters, defeated mothers","note":"","sourceLineIndex":26},{"id":"cyrano-de-bergerac-14-027","lineIndex":27,"speaker":"","original":"Tu veux d'l'amour j'vais t'en donner","ipa":"/ty vø dəlamə ʒvɛ tɑ̃ dɔne/","zh":"你不是想要爱吗？我会给你爱","en":"You want love, I will give it to you","note":"","sourceLineIndex":27},{"id":"cyrano-de-bergerac-14-028","lineIndex":28,"speaker":"","original":"Fais tes valises c'est ta tournée","ipa":"/fɛ te valiz sɛ ta tuʁne/","zh":"收拾行李吧，这是你的巡演","en":"Pack your bags, it's your tour","note":"","sourceLineIndex":28},{"id":"cyrano-de-bergerac-14-029","lineIndex":29,"speaker":"","original":"Avec des bravos pleins la tête","ipa":"/avɛk de bʁavo plɛ̃ la tɛt/","zh":"满脑子的喝彩声","en":"With a head full of bravos","note":"","sourceLineIndex":29},{"id":"cyrano-de-bergerac-14-030","lineIndex":30,"speaker":"","original":"T'oublieras vite tes amourettes","ipa":"/tubliʁa vit tez amuʁɛt/","zh":"你会很快忘记那些短暂恋情","en":"You'll quickly forget your crushes","note":"","sourceLineIndex":30},{"id":"cyrano-de-bergerac-14-031","lineIndex":31,"speaker":"","original":"Et pas la peine de remercier","ipa":"/e pa la pɛn də ʁəmɛʁsje/","zh":"也不用感谢我","en":"And there's no point in thanking","note":"","sourceLineIndex":31},{"id":"cyrano-de-bergerac-14-032","lineIndex":32,"speaker":"","original":"C'est pas la peine… C'est ma tournée","ipa":"/sɛ pa la pɛn sɛ ma tuʁne/","zh":"没必要…这是我的巡演","en":"It's not worth it... It's my tour","note":"","sourceLineIndex":32},{"id":"cyrano-de-bergerac-14-033","lineIndex":33,"speaker":"","original":"Avec des bravos pleins la tête","ipa":"/avɛk de bʁavo plɛ̃ la tɛt/","zh":"满脑子的喝彩声","en":"With a head full of bravos","note":"","sourceLineIndex":33},{"id":"cyrano-de-bergerac-14-034","lineIndex":34,"speaker":"","original":"T'oublieras vite tes amourettes","ipa":"/tubliʁa vit tez amuʁɛt/","zh":"你会很快忘记那些短暂恋情","en":"You'll quickly forget your crushes","note":"","sourceLineIndex":34},{"id":"cyrano-de-bergerac-14-035","lineIndex":35,"speaker":"","original":"Tu veux d'l'amour j'vais t'en donner","ipa":"/ty vø dəlamə ʒvɛ tɑ̃ dɔne/","zh":"你不是想要爱吗？我会给你爱","en":"You want love, I will give it to you","note":"","sourceLineIndex":35},{"id":"cyrano-de-bergerac-14-036","lineIndex":36,"speaker":"","original":"Fais tes valises c'est ta tournée","ipa":"/fɛ te valiz sɛ ta tuʁne/","zh":"收拾行李吧，这是你的巡演","en":"Pack your bags, it's your tour","note":"","sourceLineIndex":36},{"id":"cyrano-de-bergerac-14-037","lineIndex":37,"speaker":"","original":"Arrête un peu de faire la tête","ipa":"/aʁɛt œ̃ pø də fɛʁ la tɛt/","zh":"别摆出那副表情了","en":"Stop sulking for a bit","note":"","sourceLineIndex":37},{"id":"cyrano-de-bergerac-14-038","lineIndex":38,"speaker":"","original":"Maint'nant c'est d'jet set et paillettes","ipa":"/meɪntnənt sɛ dʒɛ sɛt e pajɛt/","zh":"现在是明星圈子和闪光灯","en":"Now it's jet set and glitter","note":"","sourceLineIndex":38},{"id":"cyrano-de-bergerac-14-039","lineIndex":39,"speaker":"","original":"T'auras vite fait de l'oublier","ipa":"/toʁa vit fɛ də lublie/","zh":"你很快就会习惯的","en":"You'll quickly forget it","note":"","sourceLineIndex":39},{"id":"cyrano-de-bergerac-14-040","lineIndex":40,"speaker":"","original":"Viens boire un coup… on va trinquer…c'est ma tournée","ipa":"/vjɛ̃ bwaʁ œ̃ ku ɔ̃ va tʁɛ̃ke sɛ ma tuʁne/","zh":"来喝一杯…我们干杯…这是我的巡演","en":"Come have a drink... we're going to toast... it's my tour","note":"","sourceLineIndex":40}],"sourceOrder":14,"displayOrder":14},{"order":15,"id":"15-l-ame-dans-l-encrier","title":"L'Ame dans l'encrier","titleZh":"灵魂入墨","lines":[{"id":"cyrano-de-bergerac-15-001","lineIndex":1,"speaker":"","original":"J'attendrai toute ma vie, toute ma vie s'il le faut","ipa":"/ʒatɑ̃dʁe tut ma vi tut ma vi sil lə fo/","zh":"我愿等他一生 若有必要就等他一生","en":"I'll wait all my life, all my life if necessary","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-15-002","lineIndex":2,"speaker":"","original":"C'est Christian ou personne","ipa":"/sɛ kʁistjɑ̃ u pɛʁsɔn/","zh":"我只认克里斯蒂安 无可代替","en":"It's Christian or no one","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-15-003","lineIndex":3,"speaker":"","original":"Pars suivre sa tournée, qu'il m'envoie quelques mots","ipa":"/paʁ sɥivʁ sa tuʁne kil mɑ̃vwa kɛlkə mo/","zh":"跟他去巡演吧 让他给我寄几句话来就好","en":"Go follow his tour, let him send me a few words","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-15-004","lineIndex":4,"speaker":"","original":"Chaque nuit que Dieu fait","ipa":"/ʃak nɥi kə djø fɛ/","zh":"在每个神赐的夜晚","en":"Every night that God makes","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-15-005","lineIndex":5,"speaker":"","original":"Si mon stylo s'allume, si j'écris pour Christian","ipa":"/si mɔ̃ stilo salym si ʒekʁi puʁ kʁistjɑ̃/","zh":"每当我提起笔 每当我替克里斯蒂安写作","en":"If my pen lights up, if I write for Christian","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-15-006","lineIndex":6,"speaker":"","original":"Roxane c'est mon sang qui coule dans ma plume","ipa":"/ʁoksan sɛ mɔ̃ sɑ̃ ki kul dɑ̃ ma plym/","zh":"罗克珊 是我的鲜血流淌在笔尖","en":"Roxane it's my blood that flows in my pen","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-15-007","lineIndex":7,"speaker":"","original":"Dis-lui qu'il m'écrive quelques mots","ipa":"/dilɥi kil mekʁiv kɛlkə mo/","zh":"告诉他 让他给我写上只言片语","en":"Tell him to write me a few words","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-15-008","lineIndex":8,"speaker":"","original":"Qu'il m'écrive chaque jour Cyrano","ipa":"/kil mekʁiv ʃak ʒuʁ siʁano/","zh":"让他每天都记得写 西哈诺","en":"Let him write to me every day Cyrano","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-15-009","lineIndex":9,"speaker":"","original":"Roxane trouvera dans mes mots tout l'amour qu'il lui faut","ipa":"/ʁoksan tʁuvʁa dɑ̃ me mo tu lamuʁ kil lɥi fo/","zh":"罗克珊会在我的字句里找到她需要的爱情","en":"Roxane will find in my words all the love she needs","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-15-010","lineIndex":10,"speaker":"","original":"Dis-lui qu'il m'écrive s'il te plaît","ipa":"/dilɥi kil mekʁiv sil tə plɛ/","zh":"告诉他 让他给我写信 拜托了","en":"Tell him to write to me please","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-15-011","lineIndex":11,"speaker":"","original":"J'écrirai chaque jour que Dieu fait","ipa":"/ʒekʁiʁe ʃak ʒuʁ kə djø fɛ/","zh":"我会在每个神赐的日子写下去","en":"I will write every day that God wishes","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-15-012","lineIndex":12,"speaker":"","original":"Je mettrai pour toi mon cœur sur le papier, l'âme dans l'encrier","ipa":"/ʒə mɛtʁe puʁ twa mɔ̃ kœʁ syʁ lə papje lam dɑ̃ lɑ̃kʁie/","zh":"我将为你把心铺纸 把灵魂入墨","en":"I will put my heart on paper for you, my soul in the inkwell","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-15-013","lineIndex":13,"speaker":"","original":"Caché sous mes paupières, il habite mes nuits, et j'attends le sommeil","ipa":"/kaʃe su me popjɛʁ il abit me nɥi e ʒatɑ̃ lə sɔmɛj/","zh":"他藏在我眼帘 思念整夜不散 我等待着入眠","en":"Hidden under my eyelids, he inhabits my nights, and I wait for sleep","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-15-014","lineIndex":14,"speaker":"","original":"Pour naître dans ses bras et partir avec lui","ipa":"/puʁ nɛtʁ dɑ̃ se bʁaz e paʁtiʁ avɛk lɥi/","zh":"好在梦里依偎在他怀中 与他双宿双飞","en":"To be born in his arms and leave with him","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-15-015","lineIndex":15,"speaker":"","original":"J'écrirai la musique, d'un cœur qui souffre trop, et je jure que même si","ipa":"/ʒekʁiʁe la myzik dœ̃ kœʁ ki sufʁ tʁo e ʒə ʒyʁ kə mɛm si/","zh":"我将把沉痛的心 化作笔下的旋律 我发誓即使","en":"I will write music, with a heart that suffers too much, and I swear that even if","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-15-016","lineIndex":16,"speaker":"","original":"Elle n'aime pas mes traits, elle aimera mes mots","ipa":"/ɛl nɛm pa me tʁɛ ɛl ɛmʁa me mo/","zh":"她不爱我的容貌 也将爱上我的词句","en":"She doesn't like my features, she will love my words","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-15-017","lineIndex":17,"speaker":"","original":"Dis-lui qu'il m'écrive quelques mots","ipa":"/dilɥi kil mekʁiv kɛlkə mo/","zh":"告诉他 让他给我写上只言片语","en":"Tell him to write me a few words","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-15-018","lineIndex":18,"speaker":"","original":"Qu'il m'écrive chaque jour Cyrano","ipa":"/kil mekʁiv ʃak ʒuʁ siʁano/","zh":"让他每天都记得写 西哈诺","en":"Let him write to me every day Cyrano","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-15-019","lineIndex":19,"speaker":"","original":"Roxane trouvera dans mes mots tout l'amour qu'il lui faut","ipa":"/ʁoksan tʁuvʁa dɑ̃ me mo tu lamuʁ kil lɥi fo/","zh":"罗克珊会在我的字句里找到她需要的爱情","en":"Roxane will find in my words all the love she needs","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-15-020","lineIndex":20,"speaker":"","original":"Dis-lui qu'il m'écrive s'il te plaît","ipa":"/dilɥi kil mekʁiv sil tə plɛ/","zh":"告诉他 让他给我写信 拜托了","en":"Tell him to write to me please","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-15-021","lineIndex":21,"speaker":"","original":"J'écrirai chaque jour que Dieu fait","ipa":"/ʒekʁiʁe ʃak ʒuʁ kə djø fɛ/","zh":"我会在每个神赐的日子写下去","en":"I will write every day that God wishes","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-15-022","lineIndex":22,"speaker":"","original":"Je mettrai pour toi mon cœur sur le papier, l'âme dans l'encrier","ipa":"/ʒə mɛtʁe puʁ twa mɔ̃ kœʁ syʁ lə papje lam dɑ̃ lɑ̃kʁie/","zh":"我将为你把心铺纸 把灵魂入墨","en":"I will put my heart on paper for you, my soul in the inkwell","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-15-023","lineIndex":23,"speaker":"","original":"J'écrirai pour Christian, l'âme dans l'encrier","ipa":"/ʒekʁiʁe puʁ kʁistjɑ̃ lam dɑ̃ lɑ̃kʁie/","zh":"我会替克里斯蒂安写作 把灵魂入墨","en":"I will write for Christian, the soul in the inkwell","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-15-024","lineIndex":24,"speaker":"","original":"Tu liras rouge sur blanc, mon cœur sur le papier","ipa":"/ty liʁa ʁuʒ syʁ blɑ̃ mɔ̃ kœʁ syʁ lə papje/","zh":"你会在白纸上 读见我鲜红的心","en":"You will read red on white, my heart on the paper","note":"","sourceLineIndex":24}],"sourceOrder":15,"displayOrder":15},{"order":16,"id":"16-la-lettre","title":"La lettre","titleZh":"信","lines":[{"id":"cyrano-de-bergerac-16-001","lineIndex":1,"speaker":"","original":"Il fait froid aujourd'hui","ipa":"/il fɛ fʁwa oʒuʁdɥi/","zh":"今天天气寒冷","en":"It's cold today","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-16-002","lineIndex":2,"speaker":"","original":"Froid à fendre les pierres","ipa":"/fʁwa a fɑ̃dʁ le pjɛʁ/","zh":"冷得冻裂顽石","en":"Cold to split stones","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-16-003","lineIndex":3,"speaker":"","original":"A geler mes envies","ipa":"/a ʒəle mez ɑ̃vi/","zh":"凝结我的欲想","en":"To freeze my desires","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-16-004","lineIndex":4,"speaker":"","original":"A glacer mes prières","ipa":"/a ɡlase me pʁiɛʁ/","zh":"霜冻我的祈祷","en":"To freeze my prayers","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-16-005","lineIndex":5,"speaker":"","original":"Il fait froid aujourd'hui","ipa":"/il fɛ fʁwa oʒuʁdɥi/","zh":"今天天气寒冷","en":"It's cold today","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-16-006","lineIndex":6,"speaker":"","original":"Et j'ai plus froid qu'hier","ipa":"/e ʒe ply fʁwa kwhiə/","zh":"于我更甚昨日","en":"And I am colder than yesterday","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-16-007","lineIndex":7,"speaker":"","original":"J'étais au paradis","ipa":"/ʒetɛz o paʁadi/","zh":"我曾身处天堂","en":"I was in paradise","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-16-008","lineIndex":8,"speaker":"","original":"Je suis seul sur la terre","ipa":"/ʒə sɥi sœl syʁ la tɛʁ/","zh":"如今独在人间","en":"I am alone on earth","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-16-009","lineIndex":9,"speaker":"","original":"Ma vie se vide de tout sens","ipa":"/ma vi sə vid də tu sɑ̃s/","zh":"我的生活日益空虚","en":"My life is emptying of all meaning","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-16-010","lineIndex":10,"speaker":"","original":"Elle se remplit de ton absence","ipa":"/ɛl sə ʁɑ̃pli də tɔ̃n absɑ̃s/","zh":"满是你缺席的留白","en":"It is filled with your absence","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-16-011","lineIndex":11,"speaker":"","original":"Plus je t'oublie et plus j'y pense","ipa":"/ply ʒə tubli e ply ʒi pɑ̃s/","zh":"越想忘却越是思念","en":"The more I forget you, the more I think about it","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-16-012","lineIndex":12,"speaker":"","original":"Tout seul au fond des nuits de pénitence","ipa":"/tu sœl o fɔ̃ de nɥi də penitɑ̃s/","zh":"孤身捱过幽深长夜","en":"All alone in the depths of the nights of penitence","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-16-013","lineIndex":13,"speaker":"","original":"Je pense à toi...","ipa":"/ʒə pɑ̃s a twa/","zh":"我想你了","en":"I think of you...","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-16-014","lineIndex":14,"speaker":"","original":"Il fait sombre aujourd'hui","ipa":"/il fɛ sɔ̃bʁ oʒuʁdɥi/","zh":"今天天色阴沉","en":"It's dark today","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-16-015","lineIndex":15,"speaker":"","original":"Et tu es ma lumière","ipa":"/e ty ɛ ma lymjɛʁ/","zh":"而你是我的光","en":"And you are my light","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-16-016","lineIndex":16,"speaker":"","original":"C'est pour ça que j'écris","ipa":"/sɛ puʁ sa kə ʒekʁi/","zh":"因此我才提笔","en":"That's why I write","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-16-017","lineIndex":17,"speaker":"","original":"Pour conjurer l'hiver","ipa":"/puʁ kɔ̃ʒyʁe livɛʁ/","zh":"以求驱散寒冬","en":"To ward off winter","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-16-018","lineIndex":18,"speaker":"","original":"Si le vent et la pluie","ipa":"/si lə vɑ̃ e la plɥi/","zh":"哪怕凄风苦雨","en":"If the wind and the rain","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-16-019","lineIndex":19,"speaker":"","original":"Font baisser mes paupières","ipa":"/fɔ̃ bɛse me popjɛʁ/","zh":"捶打在我眼帘","en":"Make my eyelids droop","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-16-020","lineIndex":20,"speaker":"","original":"Cette lettre nous lie","ipa":"/sɛt lɛtʁ nu li/","zh":"这封信把你我相连","en":"This letter binds us","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-16-021","lineIndex":21,"speaker":"","original":"Et tout le ciel s'éclaire","ipa":"/e tu lə sjɛl seklɛʁ/","zh":"天空也随之澄明","en":"And the whole sky lights up","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-16-022","lineIndex":22,"speaker":"","original":"Ma vie se vide de tout sens","ipa":"/ma vi sə vid də tu sɑ̃s/","zh":"我的生活日益空虚","en":"My life is emptying of all meaning","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-16-023","lineIndex":23,"speaker":"","original":"Elle se remplit de ton absence","ipa":"/ɛl sə ʁɑ̃pli də tɔ̃n absɑ̃s/","zh":"满是你缺席的留白","en":"It is filled with your absence","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-16-024","lineIndex":24,"speaker":"","original":"Plus je t'oublie et plus j'y pense","ipa":"/ply ʒə tubli e ply ʒi pɑ̃s/","zh":"越想忘却越是思念","en":"The more I forget you, the more I think about it","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-16-025","lineIndex":25,"speaker":"","original":"Tout seul au long des nuits de pénitence, sans toi...","ipa":"/tu sœl o lɔ̃ de nɥi də penitɑ̃s sɑ̃ twa/","zh":"独身捱过没有你的漫漫长夜","en":"All alone throughout the nights of penitence, without you...","note":"","sourceLineIndex":25},{"id":"cyrano-de-bergerac-16-026","lineIndex":26,"speaker":"","original":"De pages blanches en confidence","ipa":"/də paʒ blɑ̃ʃz ɑ̃ kɔ̃fidɑ̃s/","zh":"在页页白纸上倾诉心声","en":"From white pages in confidence","note":"","sourceLineIndex":26},{"id":"cyrano-de-bergerac-16-027","lineIndex":27,"speaker":"","original":"Entre les lignes en transparence","ipa":"/ɑ̃tʁ le linjz ɑ̃ tʁɑ̃spaʁɑ̃s/","zh":"在这字里行间吐露真情","en":"Between the lines in transparency","note":"","sourceLineIndex":27},{"id":"cyrano-de-bergerac-16-028","lineIndex":28,"speaker":"","original":"L'encre bleue de mes espérances","ipa":"/lɑ̃kʁ blø də mez ɛspeʁɑ̃s/","zh":"蓝色墨痕承载我的期许","en":"The blue ink of my hopes","note":"","sourceLineIndex":28},{"id":"cyrano-de-bergerac-16-029","lineIndex":29,"speaker":"","original":"Dessine l'ombre claire de ta présence","ipa":"/dɛsin lɔ̃bʁ klɛʁ də ta pʁezɑ̃s/","zh":"栩栩如生勾勒出你身影","en":"Draw the clear shadow of your presence","note":"","sourceLineIndex":29},{"id":"cyrano-de-bergerac-16-030","lineIndex":30,"speaker":"","original":"Je pense à toi","ipa":"/ʒə pɑ̃s a twa/","zh":"我想你了","en":"I think of you","note":"","sourceLineIndex":30}],"sourceOrder":16,"displayOrder":16},{"order":17,"id":"17-bien-plus-loin-que-toi-meme","title":"Bien plus loin que toi même","titleZh":"更深层的你","lines":[{"id":"cyrano-de-bergerac-17-001","lineIndex":1,"speaker":"","original":"Jour après jour","ipa":"/ʒuʁ apʁɛ ʒuʁ/","zh":"日复一日","en":"Day after day","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-17-002","lineIndex":2,"speaker":"","original":"J'oublie l'image","ipa":"/ʒubli limaʒ/","zh":"我逐渐忘记","en":"I forget the image","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-17-003","lineIndex":3,"speaker":"","original":"De ton visage","ipa":"/də tɔ̃ vizaʒ/","zh":"你的面容","en":"Of your face","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-17-004","lineIndex":4,"speaker":"","original":"Mais mon amour","ipa":"/mɛ mɔ̃n amuʁ/","zh":"可我的爱","en":"But my love","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-17-005","lineIndex":5,"speaker":"","original":"Dans tes poèmes","ipa":"/dɑ̃ te pɔɛm/","zh":"在你的诗中","en":"In your poems","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-17-006","lineIndex":6,"speaker":"","original":"Brûle une flamme","ipa":"/bʁyl yn flam/","zh":"熊熊燃烧","en":"Burns a flame","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-17-007","lineIndex":7,"speaker":"","original":"Je vois ton âme","ipa":"/ʒə vwa tɔ̃n am/","zh":"我看见你的灵魂","en":"I see your soul","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-17-008","lineIndex":8,"speaker":"","original":"Et bien plus loin que toi-même","ipa":"/e bjɛ̃ ply lwɛ̃ kə twamɛm/","zh":"看见更深层的你","en":"And much further than yourself","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-17-009","lineIndex":9,"speaker":"","original":"Maintenant c'est vraiment toi que j'aime","ipa":"/mɛ̃tnɑ̃ sɛ vʁɛmɑ̃ twa kə ʒɛm/","zh":"如今我真正爱上了你","en":"Now it's really you that I love","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-17-010","lineIndex":10,"speaker":"","original":"C'est toi dans chaque lettre","ipa":"/sɛ twa dɑ̃ ʃak lɛtʁ/","zh":"在每一封信中","en":"It's you in each letter","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-17-011","lineIndex":11,"speaker":"","original":"Que je vois apparaître","ipa":"/kə ʒə vwaz apaʁɛtʁ/","zh":"我都看见你的身影","en":"That I see appearing","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-17-012","lineIndex":12,"speaker":"","original":"Tes mots sont plus forts que toi-même","ipa":"/te mo sɔ̃ ply fɔʁ kə twamɛm/","zh":"你的文字比你本人更有力","en":"Your words are stronger than yourself","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-17-013","lineIndex":13,"speaker":"","original":"Maintenant c'est vraiment toi que j'aime","ipa":"/mɛ̃tnɑ̃ sɛ vʁɛmɑ̃ twa kə ʒɛm/","zh":"如今我真正爱上了你","en":"Now it's really you that I love","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-17-014","lineIndex":14,"speaker":"","original":"Au fil de tes mots chaque jour","ipa":"/o fil də te mo ʃak ʒuʁ/","zh":"循着你每日的字句","en":"Through your words every day","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-17-015","lineIndex":15,"speaker":"","original":"Se dessine un autre amour","ipa":"/sə dɛsin œ̃n otʁ amuʁ/","zh":"另一段爱情悄然而生","en":"Another love takes shape","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-17-016","lineIndex":16,"speaker":"","original":"Il remplace mon visage","ipa":"/il ʁɑ̃plas mɔ̃ vizaʒ/","zh":"取代了我的容颜","en":"It replaces my face","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-17-017","lineIndex":17,"speaker":"","original":"Dans tes phrases à chaque page","ipa":"/dɑ̃ te fʁazz a ʃak paʒ/","zh":"在每页的字里行间","en":"In your sentences on each page","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-17-018","lineIndex":18,"speaker":"","original":"Crois-moi c'est toi qu'elle aime vraiment","ipa":"/kʁwamwa sɛ twa kɛl ɛm vʁɛmɑ̃/","zh":"相信我，她真正爱的是你","en":"Believe me, it's you she really loves","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-17-019","lineIndex":19,"speaker":"","original":"Comment penser qu'elle peut m'aimer","ipa":"/kɔmɑ̃ pɑ̃se kɛl pø mɛme/","zh":"怎么敢想她会爱上我","en":"How to think that she can love me","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-17-020","lineIndex":20,"speaker":"","original":"Pourquoi lui dire la vérité","ipa":"/puʁkwa lɥi diʁ la veʁite/","zh":"何必告诉她真相","en":"Why tell her the truth","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-17-021","lineIndex":21,"speaker":"","original":"Et si j'ai su écrire pour toi","ipa":"/e si ʒe sy ekʁiʁ puʁ twa/","zh":"即使是我为你写下这些","en":"And if I knew how to write for you","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-17-022","lineIndex":22,"speaker":"","original":"C'est toi qu'elle aime à travers moi","ipa":"/sɛ twa kɛl ɛm a tʁavɛʁ mwa/","zh":"她借由我爱着的仍是你","en":"It is you that she loves through me","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-17-023","lineIndex":23,"speaker":"","original":"Crois-moi c'est toi qu'elle aime vraiment","ipa":"/kʁwamwa sɛ twa kɛl ɛm vʁɛmɑ̃/","zh":"相信我 她真正爱的是你","en":"Believe me, it's you she really loves","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-17-024","lineIndex":24,"speaker":"","original":"Je ne suis qu'un mirage","ipa":"/ʒə nə sɥi kœ̃ miʁaʒ/","zh":"我只是一道幻影","en":"I am only a mirage","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-17-025","lineIndex":25,"speaker":"","original":"Par tes mots je lui mens","ipa":"/paʁ te mo ʒə lɥi mɑ̃/","zh":"你的字句成了我对她的谎言","en":"With your words I lie to her","note":"","sourceLineIndex":25},{"id":"cyrano-de-bergerac-17-026","lineIndex":26,"speaker":"","original":"Parle-lui maintenant…","ipa":"/paʁllɥi mɛ̃tnɑ̃/","zh":"现在就告诉她吧……","en":"Talk to her now...","note":"","sourceLineIndex":26},{"id":"cyrano-de-bergerac-17-027","lineIndex":27,"speaker":"","original":"Jour après jour","ipa":"/ʒuʁ apʁɛ ʒuʁ/","zh":"日复一日","en":"Day after day","note":"","sourceLineIndex":27},{"id":"cyrano-de-bergerac-17-028","lineIndex":28,"speaker":"","original":"Soir après soir","ipa":"/swaʁ apʁɛ swaʁ/","zh":"夜复一夜","en":"Evening after evening","note":"","sourceLineIndex":28},{"id":"cyrano-de-bergerac-17-029","lineIndex":29,"speaker":"","original":"S'écrit l'histoire","ipa":"/sekʁi listwaʁ/","zh":"缓缓写就着","en":"The story is being written","note":"","sourceLineIndex":29},{"id":"cyrano-de-bergerac-17-030","lineIndex":30,"speaker":"","original":"De votre amour","ipa":"/də votʁ amuʁ/","zh":"你们的爱情故事","en":"Of your love","note":"","sourceLineIndex":30},{"id":"cyrano-de-bergerac-17-031","lineIndex":31,"speaker":"","original":"Dans tes poèmes","ipa":"/dɑ̃ te pɔɛm/","zh":"在你的诗句里","en":"In your poems","note":"","sourceLineIndex":31},{"id":"cyrano-de-bergerac-17-032","lineIndex":32,"speaker":"","original":"Tes mélodies","ipa":"/te melodi/","zh":"在旋律中","en":"Your melodies","note":"","sourceLineIndex":32},{"id":"cyrano-de-bergerac-17-033","lineIndex":33,"speaker":"","original":"Je la trahis","ipa":"/ʒə la tʁai/","zh":"我背叛了她","en":"I betray her","note":"","sourceLineIndex":33},{"id":"cyrano-de-bergerac-17-034","lineIndex":34,"speaker":"","original":"Et bien plus loin que toi-même","ipa":"/e bjɛ̃ ply lwɛ̃ kə twamɛm/","zh":"比你自己更深","en":"And much further than yourself","note":"","sourceLineIndex":34},{"id":"cyrano-de-bergerac-17-035","lineIndex":35,"speaker":"","original":"Crois-moi c'est vraiment toi qu'elle aime","ipa":"/kʁwamwa sɛ vʁɛmɑ̃ twa kɛl ɛm/","zh":"相信我 她真正爱的是你","en":"Believe me, it's really you that she loves","note":"","sourceLineIndex":35},{"id":"cyrano-de-bergerac-17-036","lineIndex":36,"speaker":"","original":"Comment penser","ipa":"/kɔmɑ̃ pɑ̃se/","zh":"怎么敢想","en":"How to think","note":"","sourceLineIndex":36},{"id":"cyrano-de-bergerac-17-037","lineIndex":37,"speaker":"","original":"Qu'elle peut m'aimer","ipa":"/kɛl pø mɛme/","zh":"她会爱上我","en":"That she can love me","note":"","sourceLineIndex":37},{"id":"cyrano-de-bergerac-17-038","lineIndex":38,"speaker":"","original":"Elle peut t'aimer…","ipa":"/ɛl pø tɛme/","zh":"她会爱上你……","en":"She can love you…","note":"","sourceLineIndex":38},{"id":"cyrano-de-bergerac-17-039","lineIndex":39,"speaker":"","original":"C'est toi dans chaque lettre","ipa":"/sɛ twa dɑ̃ ʃak lɛtʁ/","zh":"在每一封信中","en":"It's you in each letter","note":"","sourceLineIndex":39},{"id":"cyrano-de-bergerac-17-040","lineIndex":40,"speaker":"","original":"Qu'elle voit apparaître","ipa":"/kɛl vwa apaʁɛtʁ/","zh":"她都看见你的身影","en":"That she sees appearing","note":"","sourceLineIndex":40},{"id":"cyrano-de-bergerac-17-041","lineIndex":41,"speaker":"","original":"Tes mots sont plus forts que toi-même","ipa":"/te mo sɔ̃ ply fɔʁ kə twamɛm/","zh":"你的文字比你本人更有力","en":"Your words are stronger than yourself","note":"","sourceLineIndex":41},{"id":"cyrano-de-bergerac-17-042","lineIndex":42,"speaker":"","original":"Crois-moi c'est vraiment toi qu'elle aime","ipa":"/kʁwamwa sɛ vʁɛmɑ̃ twa kɛl ɛm/","zh":"相信我 她真正爱的是你","en":"Believe me, it's really you that she loves","note":"","sourceLineIndex":42},{"id":"cyrano-de-bergerac-17-043","lineIndex":43,"speaker":"","original":"Je ne lui parlerai pas","ipa":"/ʒə nə lɥi paʁləʁe pa/","zh":"我不会告诉她","en":"I won't talk to her","note":"","sourceLineIndex":43},{"id":"cyrano-de-bergerac-17-044","lineIndex":44,"speaker":"","original":"Je ne veux pas que son amour ne meure","ipa":"/ʒə nə vø pa kə sɔ̃n amuʁ nə mœʁ/","zh":"我不忍让她的爱","en":"I do not want his love to die","note":"","sourceLineIndex":44},{"id":"cyrano-de-bergerac-17-045","lineIndex":45,"speaker":"","original":"Une seconde fois","ipa":"/yn səɡɔ̃d fwa/","zh":"再次死去","en":"A second time","note":"","sourceLineIndex":45},{"id":"cyrano-de-bergerac-17-046","lineIndex":46,"speaker":"","original":"En mourant dans son cœur","ipa":"/ɑ̃ muʁɑ̃ dɑ̃ sɔ̃ kœʁ/","zh":"死在她的心中","en":"By dying in his heart","note":"","sourceLineIndex":46},{"id":"cyrano-de-bergerac-17-047","lineIndex":47,"speaker":"","original":"Jour après jour","ipa":"/ʒuʁ apʁɛ ʒuʁ/","zh":"日复一日","en":"Day after day","note":"","sourceLineIndex":47},{"id":"cyrano-de-bergerac-17-048","lineIndex":48,"speaker":"","original":"Dans ma mémoire","ipa":"/dɑ̃ ma memwaʁ/","zh":"在我的回忆中","en":"In my memory","note":"","sourceLineIndex":48},{"id":"cyrano-de-bergerac-17-049","lineIndex":49,"speaker":"","original":"Vivra l'histoire","ipa":"/vivʁa listwaʁ/","zh":"都将留存着","en":"Will live the story","note":"","sourceLineIndex":49},{"id":"cyrano-de-bergerac-17-050","lineIndex":50,"speaker":"","original":"De mon amour","ipa":"/də mɔ̃n amuʁ/","zh":"我的爱情故事","en":"Of my love","note":"","sourceLineIndex":50},{"id":"cyrano-de-bergerac-17-051","lineIndex":51,"speaker":"","original":"Tous les poèmes","ipa":"/tu le pɔɛm/","zh":"所有的诗句","en":"All poems","note":"","sourceLineIndex":51},{"id":"cyrano-de-bergerac-17-052","lineIndex":52,"speaker":"","original":"Chantent son âme","ipa":"/ʃɑ̃t sɔ̃n am/","zh":"都歌咏着他（她）的灵魂","en":"His soul sings","note":"","sourceLineIndex":52},{"id":"cyrano-de-bergerac-17-053","lineIndex":53,"speaker":"","original":"Et chaque larme","ipa":"/e ʃak laʁm/","zh":"每一滴泪水","en":"And each tear","note":"","sourceLineIndex":53},{"id":"cyrano-de-bergerac-17-054","lineIndex":54,"speaker":"","original":"Au plus profond de ma peine","ipa":"/o ply pʁofɔ̃ də ma pɛn/","zh":"在我的痛苦深处","en":"In the depths of my pain","note":"","sourceLineIndex":54},{"id":"cyrano-de-bergerac-17-055","lineIndex":55,"speaker":"","original":"Me disent que c'est vraiment toi que j'aime","ipa":"/mə diz kə sɛ vʁɛmɑ̃ twa kə ʒɛm/","zh":"都提醒我：我真正爱的人是你","en":"Tells me that it is truly you that I love","note":"","sourceLineIndex":55},{"id":"cyrano-de-bergerac-17-056","lineIndex":56,"speaker":"","original":"À jamais c'est vraiment toi que j'aime","ipa":"/a ʒamɛ sɛ vʁɛmɑ̃ twa kə ʒɛm/","zh":"直到永远 我真正爱的人是你","en":"Forever it is truly you that I love","note":"","sourceLineIndex":56}],"sourceOrder":17,"displayOrder":17},{"order":18,"id":"18-si-tu-m-aimes-encore","title":"Si tu m'aimes encore","titleZh":"若你依然爱我","lines":[{"id":"cyrano-de-bergerac-18-001","lineIndex":1,"speaker":"","original":"J'ai cru me perdre lorsque je t'ai perdu","ipa":"/ʒe kʁy mə pɛʁdʁ lɔʁskə ʒə te pɛʁdy/","zh":"我曾以为失去你便迷失了自己","en":"I thought I was losing myself when I lost you","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-18-002","lineIndex":2,"speaker":"","original":"Tellement voulu mourir que j'en ai survécu","ipa":"/tɛlmɑ̃ vuly muʁiʁ kə ʒɑ̃n e syʁveky/","zh":"求死之切竟让我幸存于世","en":"Wanted to die so much that I survived","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-18-003","lineIndex":3,"speaker":"","original":"J'apprendrai à danser sans toi","ipa":"/ʒapʁɑ̃dʁe a dɑ̃se sɑ̃ twa/","zh":"我将学会在没有你的世界里起舞","en":"I will learn to dance without you","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-18-004","lineIndex":4,"speaker":"","original":"Tout passe et passera","ipa":"/tu pas e pasʁa/","zh":"万物皆逝 终将逝去","en":"Everything passes and will pass","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-18-005","lineIndex":5,"speaker":"","original":"Pour tout te dire peut-être pas","ipa":"/puʁ tu tə diʁ pøtɛtʁ pa/","zh":"或许不会把一切都说与你听","en":"To tell you the truth maybe not","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-18-006","lineIndex":6,"speaker":"","original":"Ou que tu sois","ipa":"/u kə ty swa/","zh":"无论你身在何处","en":"Wherever you are","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-18-007","lineIndex":7,"speaker":"","original":"Si tu m'aimes encore","ipa":"/si ty mɛmz ɑ̃kɔʁ/","zh":"若你依然爱我","en":"If you still love me","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-18-008","lineIndex":8,"speaker":"","original":"Si tu m'aimes encore","ipa":"/si ty mɛmz ɑ̃kɔʁ/","zh":"若你依然爱我","en":"If you still love me","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-18-009","lineIndex":9,"speaker":"","original":"J'aurai la force de rêver plus loin","ipa":"/ʒoʁe la fɔʁs də ʁɛve ply lwɛ̃/","zh":"我便有力气梦向更远的地方","en":"I will have the strength to dream further","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-18-010","lineIndex":10,"speaker":"","original":"Si tu m'aimes encore","ipa":"/si ty mɛmz ɑ̃kɔʁ/","zh":"若你依然爱我","en":"If you still love me","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-18-011","lineIndex":11,"speaker":"","original":"Si tu m'aimes encore","ipa":"/si ty mɛmz ɑ̃kɔʁ/","zh":"若你依然爱我","en":"If you still love me","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-18-012","lineIndex":12,"speaker":"","original":"J'oublierai mon chagrin","ipa":"/ʒubliʁe mɔ̃ ʃaɡʁɛ̃/","zh":"我将遗忘悲伤","en":"I will forget my sorrow","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-18-013","lineIndex":13,"speaker":"","original":"J'apprendrai le chemin","ipa":"/ʒapʁɑ̃dʁe lə ʃəmɛ̃/","zh":"重新学会前行的方向","en":"I will learn the way","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-18-014","lineIndex":14,"speaker":"","original":"Tu sais le matin","ipa":"/ty sɛ lə matɛ̃/","zh":"你可知道 清晨时分","en":"You know in the morning","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-18-015","lineIndex":15,"speaker":"","original":"La lumière me rassure","ipa":"/la lymjɛʁ mə ʁasyʁ/","zh":"光芒总能抚慰我心","en":"The light reassures me","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-18-016","lineIndex":16,"speaker":"","original":"L'hiver s'éteint","ipa":"/livɛʁ setɛ̃/","zh":"寒冬正渐渐褪去","en":"Winter fades away","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-18-017","lineIndex":17,"speaker":"","original":"Au fur et à mesure","ipa":"/o fyʁ e a məzyʁ/","zh":"一点一点消融殆尽","en":"Little by little","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-18-018","lineIndex":18,"speaker":"","original":"Le ciel allume encore une fois","ipa":"/lə sjɛl alym ɑ̃kɔʁ yn fwa/","zh":"天空又一次点亮","en":"The sky lights up once again","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-18-019","lineIndex":19,"speaker":"","original":"La vie autour de moi","ipa":"/la vi otuʁ də mwa/","zh":"我周身环绕的生命","en":"Life around me","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-18-020","lineIndex":20,"speaker":"","original":"J'entends ton cœur qui bat","ipa":"/ʒɑ̃tɑ̃ tɔ̃ kœʁ ki ba/","zh":"我听见你的心跳","en":"I hear your heart beating","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-18-021","lineIndex":21,"speaker":"","original":"Où que tu sois","ipa":"/u kə ty swa/","zh":"无论你身在何处","en":"Wherever you are","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-18-022","lineIndex":22,"speaker":"","original":"Si tu m'aimes encore","ipa":"/si ty mɛmz ɑ̃kɔʁ/","zh":"若你依然爱我","en":"If you still love me","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-18-023","lineIndex":23,"speaker":"","original":"Si tu m'aimes encore","ipa":"/si ty mɛmz ɑ̃kɔʁ/","zh":"若你依然爱我","en":"If you still love me","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-18-024","lineIndex":24,"speaker":"","original":"J'aurai la force de rêver plus loin","ipa":"/ʒoʁe la fɔʁs də ʁɛve ply lwɛ̃/","zh":"我便有力气梦向更远的地方","en":"I will have the strength to dream further","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-18-025","lineIndex":25,"speaker":"","original":"Si tu m'aimes encore","ipa":"/si ty mɛmz ɑ̃kɔʁ/","zh":"若你依然爱我","en":"If you still love me","note":"","sourceLineIndex":25},{"id":"cyrano-de-bergerac-18-026","lineIndex":26,"speaker":"","original":"Si tu m'aimes encore","ipa":"/si ty mɛmz ɑ̃kɔʁ/","zh":"若你依然爱我","en":"If you still love me","note":"","sourceLineIndex":26},{"id":"cyrano-de-bergerac-18-027","lineIndex":27,"speaker":"","original":"J'oublierai mon chagrin","ipa":"/ʒubliʁe mɔ̃ ʃaɡʁɛ̃/","zh":"我将遗忘悲伤","en":"I will forget my sorrow","note":"","sourceLineIndex":27},{"id":"cyrano-de-bergerac-18-028","lineIndex":28,"speaker":"","original":"J'apprendrai le chemin","ipa":"/ʒapʁɑ̃dʁe lə ʃəmɛ̃/","zh":"重新学会前行的方向","en":"I will learn the way","note":"","sourceLineIndex":28},{"id":"cyrano-de-bergerac-18-029","lineIndex":29,"speaker":"","original":"Pour vivre… Encore","ipa":"/puʁ vivʁ ɑ̃kɔʁ/","zh":"为了继续…活下去","en":"To live... Again","note":"","sourceLineIndex":29},{"id":"cyrano-de-bergerac-18-030","lineIndex":30,"speaker":"","original":"Si tu m'aimes encore","ipa":"/si ty mɛmz ɑ̃kɔʁ/","zh":"若你依然爱我","en":"If you still love me","note":"","sourceLineIndex":30},{"id":"cyrano-de-bergerac-18-031","lineIndex":31,"speaker":"","original":"Si tu m'aimes encore","ipa":"/si ty mɛmz ɑ̃kɔʁ/","zh":"若你依然爱我","en":"If you still love me","note":"","sourceLineIndex":31}],"sourceOrder":18,"displayOrder":18},{"order":19,"id":"19-la-ou-tu-vis","title":"Là où tu vis","titleZh":"在你生活的地方","lines":[{"id":"cyrano-de-bergerac-19-001","lineIndex":1,"speaker":"","original":"Dans le silence de ma voix sans ta voix","ipa":"/dɑ̃ lə silɑ̃s də ma vwa sɑ̃ ta vwa/","zh":"在我失去你声音的寂静里","en":"In the silence of my voice without your voice","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-19-002","lineIndex":2,"speaker":"","original":"Ces chansons que je n'écrirai pas","ipa":"/se ʃɑ̃sɔ̃ kə ʒə nekʁiʁe pa/","zh":"那些我将不再写下的歌曲","en":"These songs that I will not write","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-19-003","lineIndex":3,"speaker":"","original":"A quoi bon si tu n'les chantes pas","ipa":"/a kwa bɔ̃ si ty nle ʃɑ̃t pa/","zh":"若你不去吟唱 又有何意义","en":"What's the point if you don't sing them","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-19-004","lineIndex":4,"speaker":"","original":"Là où tu vis… Est c'qu'il y'a des jours et des nuits","ipa":"/la u ty vi ɛ skil ja de ʒuʁz e de nɥi/","zh":"在你生活的地方…是否有昼夜更替","en":"Where you live... Are there days and nights","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-19-005","lineIndex":5,"speaker":"","original":"Là où tu vis… Est c'qu'on te manque aussi parfois","ipa":"/la u ty vi ɛ skɔ̃ tə mɑ̃k osi paʁfwa/","zh":"在你生活的地方…是否偶尔也有人惦记你","en":"Where you live... Do we miss you sometimes too","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-19-006","lineIndex":6,"speaker":"","original":"Là où tu vis… Est c'que c'est vraiment l'paradis","ipa":"/la u ty vi ɛ skə sɛ vʁɛmɑ̃ lpaʁadi/","zh":"在你生活的地方…那里是否真是天堂","en":"Where you live... Is it really paradise","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-19-007","lineIndex":7,"speaker":"","original":"Là où tu vis… C'est tellement vide ici sans toi","ipa":"/la u ty vi sɛ tɛlmɑ̃ vid isi sɑ̃ twa/","zh":"在你生活的地方…这里没有你竟如此空寂","en":"Where you live... It's so empty here without you","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-19-008","lineIndex":8,"speaker":"","original":"J'ai appris lorsque tu es parti","ipa":"/ʒe apʁi lɔʁskə ty ɛ paʁti/","zh":"当你离去时我才明白","en":"I found out when you left","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-19-009","lineIndex":9,"speaker":"","original":"Pour aujourd'hui être ce que je suis","ipa":"/puʁ oʒuʁdɥi ɛtʁ sə kə ʒə sɥi/","zh":"如今的模样是宿命安排","en":"For today to be what I am","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-19-010","lineIndex":10,"speaker":"","original":"Tout s'efface pour ne garder que soi","ipa":"/tu sefas puʁ nə ɡaʁde kə swa/","zh":"万物褪色 唯余自我存在","en":"Everything disappears to keep only yourself","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-19-011","lineIndex":11,"speaker":"","original":"Le temps passe, elle pense encore à toi","ipa":"/lə tɑ̃ pas ɛl pɑ̃s ɑ̃kɔʁ a twa/","zh":"时光流逝 她却依然将你缅怀","en":"Time passes, she still thinks of you","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-19-012","lineIndex":12,"speaker":"","original":"Là où tu vis… Est c'qu'il y'a des jours et des nuits","ipa":"/la u ty vi ɛ skil ja de ʒuʁz e de nɥi/","zh":"在你生活的地方…是否有昼夜更替","en":"Where you live... Are there days and nights","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-19-013","lineIndex":13,"speaker":"","original":"Là où tu vis… Est c'qu'on te manque aussi parfois","ipa":"/la u ty vi ɛ skɔ̃ tə mɑ̃k osi paʁfwa/","zh":"在你生活的地方…是否偶尔也有人惦记你","en":"Where you live... Do we miss you sometimes too","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-19-014","lineIndex":14,"speaker":"","original":"Là où tu vis… Est c'que c'est vraiment l'paradis","ipa":"/la u ty vi ɛ skə sɛ vʁɛmɑ̃ lpaʁadi/","zh":"在你生活的地方…那里是否真是天堂","en":"Where you live... Is it really paradise","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-19-015","lineIndex":15,"speaker":"","original":"Là où tu vis... C'est tellement vide ici sans toi","ipa":"/la u ty vi sɛ tɛlmɑ̃ vid isi sɑ̃ twa/","zh":"在你生活的地方…这里没有你竟如此空寂","en":"Where you live... It's so empty here without you","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-19-016","lineIndex":16,"speaker":"","original":"Et malgré tout, malgré moi","ipa":"/e malɡʁe tu malɡʁe mwa/","zh":"纵然如此 身不由己","en":"And despite everything, despite me","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-19-017","lineIndex":17,"speaker":"","original":"Malgré ce chagrin qui me tue","ipa":"/malɡʁe sə ʃaɡʁɛ̃ ki mə ty/","zh":"尽管这悲伤将我吞噬","en":"Despite this sorrow that's killing me","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-19-018","lineIndex":18,"speaker":"","original":"Malgré tout, malgré moi","ipa":"/malɡʁe tu malɡʁe mwa/","zh":"纵然如此 身不由己","en":"Despite everything, despite myself","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-19-019","lineIndex":19,"speaker":"","original":"Ce qui était ne sera plus","ipa":"/sə ki etɛ nə səʁa ply/","zh":"逝去的终将不再复返","en":"What was will no longer be","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-19-020","lineIndex":20,"speaker":"","original":"Malgré tout, malgré moi","ipa":"/malɡʁe tu malɡʁe mwa/","zh":"纵然如此 身不由己","en":"Despite everything, despite myself","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-19-021","lineIndex":21,"speaker":"","original":"Même si j'me sens un peu perdue","ipa":"/mɛm si ʒmə sɑ̃z œ̃ pø pɛʁdy/","zh":"即使我总感到些许迷失","en":"Even if I feel a little lost","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-19-022","lineIndex":22,"speaker":"","original":"Malgré tout","ipa":"/malɡʁe tu/","zh":"纵然一切","en":"Despite everything","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-19-023","lineIndex":23,"speaker":"","original":"La vie continue…","ipa":"/la vi kɔ̃tiny/","zh":"生活仍在继续…","en":"Life goes on...","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-19-024","lineIndex":24,"speaker":"","original":"Là où tu vis… Là où tu vis… Là où tu vis… Là où tu vis…","ipa":"/la u ty vi la u ty vi la u ty vi la u ty vi/","zh":"在你生活的地方…在你生活的地方…在你生活的地方…在你生活的地方…","en":"Where you live... Where you live... Where you live... Where you live...","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-19-025","lineIndex":25,"speaker":"","original":"Là où tu vis…Est c'qu'il y'a des jours et des nuits …","ipa":"/la u ty vi ɛ skil ja de ʒuʁz e de nɥi/","zh":"在你生活的地方…是否有昼夜更替…","en":"Where you live... Are there days and nights...","note":"","sourceLineIndex":25},{"id":"cyrano-de-bergerac-19-026","lineIndex":26,"speaker":"","original":"Là où tu vis… Est c'qu'on te manque aussi parfois…","ipa":"/la u ty vi ɛ skɔ̃ tə mɑ̃k osi paʁfwa/","zh":"在你生活的地方…是否偶尔也有人惦记你…","en":"Where you live... Do you miss us sometimes too...","note":"","sourceLineIndex":26},{"id":"cyrano-de-bergerac-19-027","lineIndex":27,"speaker":"","original":"Là où tu vis… Est c'que c'est vraiment l'paradis …","ipa":"/la u ty vi ɛ skə sɛ vʁɛmɑ̃ lpaʁadi/","zh":"在你生活的地方…那里是否真是天堂…","en":"Where you live... Is it really paradise...","note":"","sourceLineIndex":27},{"id":"cyrano-de-bergerac-19-028","lineIndex":28,"speaker":"","original":"Là où tu vis … C'est tellement vide ici sans toi …","ipa":"/la u ty vi sɛ tɛlmɑ̃ vid isi sɑ̃ twa/","zh":"在你生活的地方…这里没有你竟如此空寂…","en":"Where you live... It's so empty here without you...","note":"","sourceLineIndex":28},{"id":"cyrano-de-bergerac-19-029","lineIndex":29,"speaker":"","original":"Là où tu vis…Sans toi","ipa":"/la u ty vi sɑ̃ twa/","zh":"在你生活的地方…没有你","en":"Where you live... Without you","note":"","sourceLineIndex":29},{"id":"cyrano-de-bergerac-19-030","lineIndex":30,"speaker":"","original":"Là où tu vis…C'est tellement vide ici","ipa":"/la u ty vi sɛ tɛlmɑ̃ vid isi/","zh":"在你生活的地方…这里如此空寂","en":"Where you live... It's so empty here","note":"","sourceLineIndex":30},{"id":"cyrano-de-bergerac-19-031","lineIndex":31,"speaker":"","original":"Là où tu vis… Est c'qu'on te manque aussi …","ipa":"/la u ty vi ɛ skɔ̃ tə mɑ̃k osi/","zh":"在你生活的地方…也有人思念着你…","en":"Where you live... Do we miss you too...","note":"","sourceLineIndex":31},{"id":"cyrano-de-bergerac-19-032","lineIndex":32,"speaker":"","original":"Là où tu vis... On pense encore à toi","ipa":"/la u ty vi ɔ̃ pɑ̃s ɑ̃kɔʁ a twa/","zh":"在你生活的地方…人们依然铭记你","en":"Where you live... We still think of you","note":"","sourceLineIndex":32}],"sourceOrder":19,"displayOrder":19},{"order":20,"id":"20-danseuses-etoiles","title":"Danseuses étoiles","titleZh":"首席女舞者","lines":[{"id":"cyrano-de-bergerac-20-001","lineIndex":1,"speaker":"","original":"Il faut souffrir et rêver","ipa":"/il fo sufʁiʁ e ʁɛve/","zh":"必须经历苦痛与梦想","en":"You have to suffer and dream","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-20-002","lineIndex":2,"speaker":"","original":"Travailler pour s'envoler","ipa":"/tʁavaje puʁ sɑ̃vole/","zh":"为展翅高飞而奋力修炼","en":"Work to fly away","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-20-003","lineIndex":3,"speaker":"","original":"Un jour dans la lumière des projecteurs","ipa":"/œ̃ ʒuʁ dɑ̃ la lymjɛʁ de pʁoʒɛktœʁ/","zh":"终有一日沐浴聚光灯的辉煌","en":"One day in the spotlight","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-20-004","lineIndex":4,"speaker":"","original":"Je suis là pour vous guider","ipa":"/ʒə sɥi la puʁ vu ɡide/","zh":"我在此引导你们前行","en":"I am here to guide you","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-20-005","lineIndex":5,"speaker":"","original":"Sur la pointe de vos pieds","ipa":"/syʁ la pwɛ̃t də vo pje/","zh":"踮起足尖的世界里","en":"On the tips of your toes","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-20-006","lineIndex":6,"speaker":"","original":"Tant de pas pour dessiner le bonheur","ipa":"/tɑ̃ də pa puʁ dɛsine lə bɔnœʁ/","zh":"用万千舞步勾勒幸福模样","en":"So many steps to draw happiness","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-20-007","lineIndex":7,"speaker":"","original":"J'ai tellement rêvé","ipa":"/ʒe tɛlmɑ̃ ʁɛve/","zh":"我曾如此渴望飞翔","en":"I dreamed so much","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-20-008","lineIndex":8,"speaker":"","original":"Alors dansez…","ipa":"/alɔʁ dɑ̃se/","zh":"那就起舞吧…","en":"So dance…","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-20-009","lineIndex":9,"speaker":"","original":"Danseuse étoile","ipa":"/dɑ̃søz etwal/","zh":"首席女舞者","en":"Principal dancer","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-20-010","lineIndex":10,"speaker":"","original":"J'écrirai ma vie en dansant","ipa":"/ʒekʁiʁe ma vi ɑ̃ dɑ̃sɑ̃/","zh":"我以舞步书写生命篇章","en":"I will write my life while dancing","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-20-011","lineIndex":11,"speaker":"","original":"J'en rêve depuis si longtemps","ipa":"/ʒɑ̃ ʁɛv dəpɥi si lɔ̃tɑ̃/","zh":"这梦想萦绕多年时光","en":"I've been dreaming of it for so long","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-20-012","lineIndex":12,"speaker":"","original":"Je danserai, au firmament","ipa":"/ʒə dɑ̃sʁe o fiʁmamɑ̃/","zh":"我将在苍穹翩然起舞","en":"I will dance, in the firmament","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-20-013","lineIndex":13,"speaker":"","original":"Danseuse étoile","ipa":"/dɑ̃søz etwal/","zh":"星辰舞者","en":"Principal dancer","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-20-014","lineIndex":14,"speaker":"","original":"Les salles seront des cathédrales","ipa":"/le sal səʁɔ̃ de katedʁal/","zh":"剧场将化作神圣殿堂","en":"The halls will be cathedrals","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-20-015","lineIndex":15,"speaker":"","original":"Seule dans la lumière pâle","ipa":"/sœl dɑ̃ la lymjɛʁ pal/","zh":"独舞于苍白的追光","en":"Alone in the pale light","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-20-016","lineIndex":16,"speaker":"","original":"Je danserai","ipa":"/ʒə dɑ̃sʁe/","zh":"我将起舞","en":"I will dance","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-20-017","lineIndex":17,"speaker":"","original":"Sur les étoiles, sur les étoiles…","ipa":"/syʁ lez etwal syʁ lez etwal/","zh":"于星辰之上 于星辰之上…","en":"On the stars, on the stars...","note":"","sourceLineIndex":17}],"sourceOrder":20,"displayOrder":20},{"order":21,"id":"21-quand","title":"Quand","titleZh":"当","lines":[{"id":"cyrano-de-bergerac-21-001","lineIndex":1,"speaker":"","original":"Quand, je n'serai plus qu'une étoile, à qui tu souriras","ipa":"/kɑ̃ ʒə nsəʁe ply kyn etwal a ki ty suʁiʁa/","zh":"当某天 我化作你微笑仰望的星辰","en":"When, I will be nothing more than a star, to whom you will smile","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-21-002","lineIndex":2,"speaker":"","original":"En regardant le ciel, en écoutant ma voix","ipa":"/ɑ̃ ʁəɡaʁdɑ̃ lə sjɛl ɑ̃n ekutɑ̃ ma vwa/","zh":"当你凝望天际 倾听我的声音","en":"Looking at the sky, listening to my voice","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-21-003","lineIndex":3,"speaker":"","original":"Quand le temps n'aura laissé, gravé au fond de toi","ipa":"/kɑ̃ lə tɑ̃ noʁa lɛse ɡʁave o fɔ̃ də twa/","zh":"当时光仅在你心底镌刻下","en":"When time has left, engraved deep inside you","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-21-004","lineIndex":4,"speaker":"","original":"Qu'une image un peu floue, en souvenir de moi","ipa":"/kyn imaʒ œ̃ pø flu ɑ̃ suvniʁ də mwa/","zh":"关于我模糊朦胧的残影","en":"Only a slightly blurred image, in memory of me","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-21-005","lineIndex":5,"speaker":"","original":"Quand la vie sera trop lourde","ipa":"/kɑ̃ la vi səʁa tʁo luʁd/","zh":"当生命变得过于沉重","en":"When life will be too heavy","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-21-006","lineIndex":6,"speaker":"","original":"Qu'il n'y aura que des \"pourquoi\"","ipa":"/kil ni oʁa kə de puʁkwa/","zh":"当世间只剩无解的“为什么”","en":"When there will only be \"why\"","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-21-007","lineIndex":7,"speaker":"","original":"Ferme les yeux… et pense à moi","ipa":"/fɛʁm lez jø e pɑ̃s a mwa/","zh":"闭上双眼…想着我","en":"Close your eyes... and think of me","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-21-008","lineIndex":8,"speaker":"","original":"Pense que je t'aime …","ipa":"/pɑ̃s kə ʒə tɛm/","zh":"想着我爱你…","en":"Think that I love you...","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-21-009","lineIndex":9,"speaker":"","original":"La lettre glisse des mains de Cyrano qui continue de chanter, sans lire....","ipa":"/la lɛtʁ ɡlis de mɛ̃ də siʁano ki kɔ̃tiny də ʃɑ̃te sɑ̃ liʁ/","zh":"（信纸从Cyrano手中滑落，他继续歌唱，不再阅读…）","en":"The letter slips from the hands of Cyrano who continues to sing, without reading....","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-21-010","lineIndex":10,"speaker":"","original":"Que je suis là","ipa":"/kə ʒə sɥi la/","zh":"想着我在此处","en":"That I am here","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-21-011","lineIndex":11,"speaker":"","original":"Que je t'aime","ipa":"/kə ʒə tɛm/","zh":"我爱你","en":"That I love you","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-21-012","lineIndex":12,"speaker":"","original":"Tout près de toi","ipa":"/tu pʁɛ də twa/","zh":"紧挨着你","en":"Very close to you","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-21-013","lineIndex":13,"speaker":"","original":"Que je t'aime","ipa":"/kə ʒə tɛm/","zh":"我爱你","en":"That I love you","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-21-014","lineIndex":14,"speaker":"","original":"Où que je sois","ipa":"/u kə ʒə swa/","zh":"无论我在何方","en":"Wherever I am","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-21-015","lineIndex":15,"speaker":"","original":"Que je t'aime","ipa":"/kə ʒə tɛm/","zh":"我爱你","en":"That I love you","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-21-016","lineIndex":16,"speaker":"","original":"Quand tu n'voudras plus de ces combats, quand tu voudras poser les armes","ipa":"/kɑ̃ ty nvudʁa ply də se kɔ̃ba kɑ̃ ty vudʁa poze lez aʁm/","zh":"当你厌倦争斗 当你愿卸下武装","en":"When you no longer want these fights, when you want to lay down your arms","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-21-017","lineIndex":17,"speaker":"","original":"Que tes sourires ne serviront, qu'à masquer tes larmes","ipa":"/kə te suʁiʁ nə sɛʁviʁɔ̃ ka maske te laʁm/","zh":"当你的笑容仅用来掩盖泪光","en":"That your smiles will only serve to hide your tears","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-21-018","lineIndex":18,"speaker":"","original":"Quand tu voudras tout laisser tomber, quand tu auras perdu la flamme","ipa":"/kɑ̃ ty vudʁa tu lɛse tɔ̃be kɑ̃ ty oʁa pɛʁdy la flam/","zh":"当你想放弃一切 当你失去火焰","en":"When you want to give up everything, when you have lost the flame","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-21-019","lineIndex":19,"speaker":"","original":"Que tu voudras briser ton corps, pour sauver ton âme","ipa":"/kə ty vudʁa bʁize tɔ̃ kɔʁ puʁ sove tɔ̃n am/","zh":"当你想撕裂躯体 只为拯救灵魂","en":"That you will want to break your body, to save your soul","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-21-020","lineIndex":20,"speaker":"","original":"Quand la vie sera trop lâche","ipa":"/kɑ̃ la vi səʁa tʁo laʃ/","zh":"当生命过于卑劣","en":"When life is too loose","note":"","sourceLineIndex":20},{"id":"cyrano-de-bergerac-21-021","lineIndex":21,"speaker":"","original":"A chaque fois qu'elle t'oubliera","ipa":"/a ʃak fwa kɛl tubliʁa/","zh":"每当它遗忘你时","en":"Every time it forgets you","note":"","sourceLineIndex":21},{"id":"cyrano-de-bergerac-21-022","lineIndex":22,"speaker":"","original":"Ferme les yeux… et pense à moi","ipa":"/fɛʁm lez jø e pɑ̃s a mwa/","zh":"闭上双眼…想着我","en":"Close your eyes... and think of me","note":"","sourceLineIndex":22},{"id":"cyrano-de-bergerac-21-023","lineIndex":23,"speaker":"","original":"Et pense que je t'aime","ipa":"/e pɑ̃s kə ʒə tɛm/","zh":"想着我爱你","en":"And think that I love you","note":"","sourceLineIndex":23},{"id":"cyrano-de-bergerac-21-024","lineIndex":24,"speaker":"","original":"Que je suis là","ipa":"/kə ʒə sɥi la/","zh":"想着我在此处","en":"That I am here","note":"","sourceLineIndex":24},{"id":"cyrano-de-bergerac-21-025","lineIndex":25,"speaker":"","original":"Que je t'aime","ipa":"/kə ʒə tɛm/","zh":"我爱你","en":"That I love you","note":"","sourceLineIndex":25},{"id":"cyrano-de-bergerac-21-026","lineIndex":26,"speaker":"","original":"Tout près de toi","ipa":"/tu pʁɛ də twa/","zh":"紧挨着你","en":"Very close to you","note":"","sourceLineIndex":26},{"id":"cyrano-de-bergerac-21-027","lineIndex":27,"speaker":"","original":"Que je t'aime","ipa":"/kə ʒə tɛm/","zh":"我爱你","en":"That I love you","note":"","sourceLineIndex":27},{"id":"cyrano-de-bergerac-21-028","lineIndex":28,"speaker":"","original":"Où que je sois","ipa":"/u kə ʒə swa/","zh":"无论我在何方","en":"Wherever I am","note":"","sourceLineIndex":28},{"id":"cyrano-de-bergerac-21-029","lineIndex":29,"speaker":"","original":"Que je t'aime","ipa":"/kə ʒə tɛm/","zh":"我爱你","en":"That I love you","note":"","sourceLineIndex":29},{"id":"cyrano-de-bergerac-21-030","lineIndex":30,"speaker":"","original":"Pense que je t'aime","ipa":"/pɑ̃s kə ʒə tɛm/","zh":"想着我爱你","en":"Think that I love you","note":"","sourceLineIndex":30},{"id":"cyrano-de-bergerac-21-031","lineIndex":31,"speaker":"","original":"Où que je sois","ipa":"/u kə ʒə swa/","zh":"无论我在何方","en":"Wherever I am","note":"","sourceLineIndex":31},{"id":"cyrano-de-bergerac-21-032","lineIndex":32,"speaker":"","original":"Que je t'aime","ipa":"/kə ʒə tɛm/","zh":"我爱你","en":"That I love you","note":"","sourceLineIndex":32},{"id":"cyrano-de-bergerac-21-033","lineIndex":33,"speaker":"","original":"Que je suis là","ipa":"/kə ʒə sɥi la/","zh":"想着我在此处","en":"That I am here","note":"","sourceLineIndex":33},{"id":"cyrano-de-bergerac-21-034","lineIndex":34,"speaker":"","original":"Que je t'aime","ipa":"/kə ʒə tɛm/","zh":"我爱你","en":"That I love you","note":"","sourceLineIndex":34},{"id":"cyrano-de-bergerac-21-035","lineIndex":35,"speaker":"","original":"Sache que...","ipa":"/saʃ kə/","zh":"你要知道…","en":"Know that...","note":"","sourceLineIndex":35}],"sourceOrder":21,"displayOrder":21},{"order":22,"id":"22-mais-il-l-aimait-final","title":"Mais il l'aimait (Final)","titleZh":"他始终爱着她（终曲）","lines":[{"id":"cyrano-de-bergerac-22-001","lineIndex":1,"speaker":"","original":"C'était ma vie c'est mon histoire","ipa":"/setɛ ma vi sɛ mɔ̃n istwaʁ/","zh":"这是我的一生 我的故事","en":"It was my life it's my story","note":"","sourceLineIndex":1},{"id":"cyrano-de-bergerac-22-002","lineIndex":2,"speaker":"","original":"Merci d'être venus pour l'écouter ce soir","ipa":"/mɛʁsi dɛtʁ vəny puʁ lekute sə swaʁ/","zh":"感谢你们今夜到此倾听","en":"Thank you for coming to listen to it tonight","note":"","sourceLineIndex":2},{"id":"cyrano-de-bergerac-22-003","lineIndex":3,"speaker":"","original":"Et qu'à travers ma voix reste dans vos mémoires","ipa":"/e ka tʁavɛʁ ma vwa ʁɛst dɑ̃ vo memwaʁ/","zh":"希望籍由我的声音 在你们的记忆中留下","en":"And that through my voice remains in your memories","note":"","sourceLineIndex":3},{"id":"cyrano-de-bergerac-22-004","lineIndex":4,"speaker":"","original":"Tout ceux que j'aime et qui m'aimaient","ipa":"/tu sø kə ʒɛm e ki mɛmɛ/","zh":"所有我爱的、爱我的人","en":"All those I love and who loved me","note":"","sourceLineIndex":4},{"id":"cyrano-de-bergerac-22-005","lineIndex":5,"speaker":"","original":"Ils vivent en moi mais je m'en vais","ipa":"/il vivt ɑ̃ mwa mɛ ʒə mɑ̃ vɛ/","zh":"他们活在我心中 但我也会逝去","en":"They live in me but I'm leaving","note":"","sourceLineIndex":5},{"id":"cyrano-de-bergerac-22-006","lineIndex":6,"speaker":"","original":"Qu'ils vivent en vous à tout jamais","ipa":"/kil vivt ɑ̃ vuz a tu ʒamɛ/","zh":"希望他们能在你们心中 永垂不朽","en":"May they live in you forever","note":"","sourceLineIndex":6},{"id":"cyrano-de-bergerac-22-007","lineIndex":7,"speaker":"","original":"À tout jamais","ipa":"/a tu ʒamɛ/","zh":"永垂不朽","en":"Forever","note":"","sourceLineIndex":7},{"id":"cyrano-de-bergerac-22-008","lineIndex":8,"speaker":"","original":"Et quand il rentrera chez Dieu","ipa":"/e kɑ̃t il ʁɑ̃tʁəʁa ʃe djø/","zh":"待他归于上帝的天国","en":"And when he goes home to God","note":"","sourceLineIndex":8},{"id":"cyrano-de-bergerac-22-009","lineIndex":9,"speaker":"","original":"Son salut balaiera largement le seuil bleu","ipa":"/sɔ̃ saly balɛʁa laʁʒəmɑ̃ lə sœj blø/","zh":"他的救赎将掠过那蔚蓝之门","en":"His greeting will sweep wide across the blue threshold","note":"","sourceLineIndex":9},{"id":"cyrano-de-bergerac-22-010","lineIndex":10,"speaker":"","original":"Il garde son panache même s'il ferme les yeux","ipa":"/il ɡaʁd sɔ̃ panaʃ mɛm sil fɛʁm lez jø/","zh":"闭上眼也不减他的气派风度","en":"He keeps his panache even if he closes his eyes","note":"","sourceLineIndex":10},{"id":"cyrano-de-bergerac-22-011","lineIndex":11,"speaker":"","original":"C'était sa vie c'est son combat","ipa":"/setɛ sa vi sɛ sɔ̃ kɔ̃ba/","zh":"这是他的一生 他的战役","en":"It was his life, it's his fight","note":"","sourceLineIndex":11},{"id":"cyrano-de-bergerac-22-012","lineIndex":12,"speaker":"","original":"L'amour le tue mais il vivra","ipa":"/lamuʁ lə ty mɛz il vivʁa/","zh":"爱把他扼杀 但他将永生","en":"Love kills him but he will live","note":"","sourceLineIndex":12},{"id":"cyrano-de-bergerac-22-013","lineIndex":13,"speaker":"","original":"Comme il l'aimait …","ipa":"/kɔm il lɛmɛ/","zh":"正如他始终爱着她","en":"As he loved her...","note":"","sourceLineIndex":13},{"id":"cyrano-de-bergerac-22-014","lineIndex":14,"speaker":"","original":"Elle l'aimera …","ipa":"/ɛl lɛmʁa/","zh":"她也将爱上他","en":"She will love him...","note":"","sourceLineIndex":14},{"id":"cyrano-de-bergerac-22-015","lineIndex":15,"speaker":"","original":"Elle l'aimera","ipa":"/ɛl lɛmʁa/","zh":"她将爱着他","en":"She will love him","note":"","sourceLineIndex":15},{"id":"cyrano-de-bergerac-22-016","lineIndex":16,"speaker":"","original":"C'était sa vie c'est son combat","ipa":"/setɛ sa vi sɛ sɔ̃ kɔ̃ba/","zh":"这是他的一生 他的战役","en":"It was his life, it's his fight","note":"","sourceLineIndex":16},{"id":"cyrano-de-bergerac-22-017","lineIndex":17,"speaker":"","original":"Comme il l'aimait …","ipa":"/kɔm il lɛmɛ/","zh":"正如他始终爱着她","en":"As he loved her...","note":"","sourceLineIndex":17},{"id":"cyrano-de-bergerac-22-018","lineIndex":18,"speaker":"","original":"Elle l'aimera …","ipa":"/ɛl lɛmʁa/","zh":"她也将爱上他","en":"She will love him...","note":"","sourceLineIndex":18},{"id":"cyrano-de-bergerac-22-019","lineIndex":19,"speaker":"","original":"Elle l'aimera","ipa":"/ɛl lɛmʁa/","zh":"她将爱着他","en":"She will love him","note":"","sourceLineIndex":19},{"id":"cyrano-de-bergerac-22-020","lineIndex":20,"speaker":"","original":"Elle l'aimera","ipa":"/ɛl lɛmʁa/","zh":"她将爱着他","en":"She will love him","note":"","sourceLineIndex":20}],"sourceOrder":22,"displayOrder":22}];
